/* =============================== APP =============================== */

class ErrorBoundary extends Component {
  constructor(p) { super(p); this.state = { error: null }; }
  static getDerivedStateFromError(error) { return { error }; }
  render() {
    if (this.state.error)
      return (
        <div style={{ padding: 20, fontFamily: "monospace", background: "#fef2f2", color: "#991b1b", minHeight: "100vh" }}>
          <p style={{ fontWeight: 700, marginBottom: 8 }}>Se cayó la app. Manda esta captura:</p>
          <pre style={{ whiteSpace: "pre-wrap", fontSize: 12 }}>{String(this.state.error?.stack || this.state.error?.message || this.state.error)}</pre>
        </div>
      );
    return this.props.children;
  }
}

export default function AdminImportaciones() {
  return (
    <ErrorBoundary>
      <App />
    </ErrorBoundary>
  );
}

function App() {
  const [vista, setVista] = useState("articulos");
  const [catalogo, setCatalogo] = useState(null);
  const [fletes, setFletes] = useState(null);
  const [pedimentos, setPedimentos] = useState(null);
  const [cuentas, setCuentas] = useState(null);
  const [operaciones, setOperaciones] = useState(null);
  const [tcFix, setTcFix] = useState(null);
  const [aviso, setAviso] = useState(null);

  /* ---- carga inicial + semilla (blindada contra datos viejos) ---- */
  useEffect(() => {
    (async () => {
      const load = async (k, seed) => {
        try {
          const r = await window.storage?.get(k);
          if (!r?.value) return seed;
          const parsed = JSON.parse(r.value);
          if (Array.isArray(seed) && !Array.isArray(parsed)) return seed;
          if (seed && typeof seed === "object" && !Array.isArray(seed) && (parsed === null || typeof parsed !== "object" || Array.isArray(parsed))) return seed;
          return parsed;
        } catch {
          return seed;
        }
      };
      setCatalogo(await load("iso3-catalogo", SEED_CATALOGO));
      setFletes(await load("iso3-fletes", SEED_FLETES));
      setPedimentos(await load("iso3-pedimentos", []));
      setCuentas(await load("iso3-cuentas", SEED_CUENTAS));
      setOperaciones(await load("iso3-operaciones", []));
      setTcFix(await load("iso3-tcfix", 17.5));
    })();
  }, []);

  const persist = useCallback(async (k, v) => {
    try {
      await window.storage?.set(k, JSON.stringify(v));
    } catch {
      setAviso({ t: "err", m: "No se pudo guardar. Revisa tu conexión e intenta de nuevo." });
    }
  }, []);

  const saveCatalogo = (c) => { setCatalogo(c); persist("iso3-catalogo", c); };
  const saveFletes = (f) => { setFletes(f); persist("iso3-fletes", f); };
  const savePedimentos = (p) => { setPedimentos(p); persist("iso3-pedimentos", p); };
  const saveCuentas = (c) => { setCuentas(c); persist("iso3-cuentas", c); };
  const saveOperaciones = (o) => { setOperaciones(o); persist("iso3-operaciones", o); };
  const saveTcFix = (t) => { setTcFix(t); persist("iso3-tcfix", t); };

  if (!catalogo || !fletes || !pedimentos || !cuentas || !operaciones || tcFix == null)
    return <div className="min-h-screen bg-stone-100 flex items-center justify-center"><p className="font-mono text-sm text-stone-500">Cargando…</p></div>;

  const pendientes = Object.values(catalogo).filter((a) => a.promedioPendiente != null).length;

  return (
    <div className="min-h-screen bg-stone-100 text-stone-900">
      <header className="bg-stone-900 text-white">
        <div className="max-w-6xl mx-auto px-4 py-3 flex flex-wrap items-center justify-between gap-2">
          <div>
            <h1 className="text-base font-semibold tracking-tight">AdminAppISO</h1>
            <p className="text-[10px] font-mono tracking-[0.2em] text-stone-400">INNOVACIÓN SOLAR</p>
          </div>
          <nav className="flex gap-1">
            {[["articulos", "Costos", pendientes], ["importaciones", "Importaciones", 0], ["tesoreria", "Tesorería", 0], ["inventario", "Inventario", 0], ["mas", "Más", 0]].map(([k, t, badge]) => (
              <button key={k} onClick={() => setVista(k)}
                className={`px-3 py-1.5 text-xs font-medium rounded transition-colors relative ${vista === k ? "bg-white text-stone-900" : "text-stone-300 hover:bg-stone-800"}`}>
                {t}
                {badge > 0 && <span className="ml-1.5 px-1.5 py-0.5 text-[9px] rounded-full bg-amber-500 text-white">{badge}</span>}
              </button>
            ))}
          </nav>
        </div>
      </header>

      <main className="max-w-6xl mx-auto px-4 py-5">
        {aviso && (
          <div className={`mb-4 px-3 py-2 rounded text-sm border ${aviso.t === "ok" ? "bg-teal-50 border-teal-300 text-teal-900" : "bg-red-50 border-red-300 text-red-900"}`}>
            {aviso.m}<button onClick={() => setAviso(null)} className="float-right text-xs underline">cerrar</button>
          </div>
        )}
        {vista === "articulos" && <Articulos catalogo={catalogo} saveCatalogo={saveCatalogo} setAviso={setAviso} />}
        {vista === "importaciones" && <Importaciones {...{ pedimentos, savePedimentos, catalogo, saveCatalogo, fletes, saveFletes, setAviso }} />}
        {vista === "inventario" && <Inventario catalogo={catalogo} saveCatalogo={saveCatalogo} setAviso={setAviso} />}
        {vista === "tesoreria" && <Tesoreria {...{ cuentas, saveCuentas, operaciones, saveOperaciones, tcFix, saveTcFix, pedimentos, setAviso }} />}
        {vista === "mas" && <Mas {...{ catalogo, fletes, pedimentos, cuentas, operaciones, tcFix, saveCatalogo, saveFletes, savePedimentos, saveCuentas, saveOperaciones, saveTcFix, setAviso }} />}
      </main>
    </div>
  );
}

/* ===================== TAB 1 · ARTÍCULOS ===================== */
function Articulos({ catalogo, saveCatalogo, setAviso }) {
  const [abierto, setAbierto] = useState(null);
  const [busca, setBusca] = useState("");
  const [verTodos, setVerTodos] = useState(false);

  const todos = Object.entries(catalogo).sort((a, b) => a[0].localeCompare(b[0]));
  const conPendiente = todos.filter(([, a]) => a.promedioPendiente != null);
  const esDeApp = (a) => (a.historia?.length || 0) > 0 || a.promedioPendiente != null;

  const q = busca.trim().toLowerCase();
  const rows = todos.filter(([sku, a]) => {
    if (!verTodos && !esDeApp(a)) return false;
    if (!q) return true;
    return sku.toLowerCase().includes(q) || (a.descripcion || "").toLowerCase().includes(q);
  });

  const enviarUno = (sku) => {
    const a = catalogo[sku];
    if (a.promedioPendiente == null) return;
    const c = { ...catalogo, [sku]: { ...a, costoVigente: a.promedioPendiente, promedioPendiente: null, ultimoEnvio: { fecha: hoy(), costo: a.promedioPendiente } } };
    saveCatalogo(c);
    setAviso({ t: "ok", m: `${sku}: nuevo promedio $${mx(a.promedioPendiente)} enviado a Zoho.` });
  };

  const enviarTodos = () => {
    const c = { ...catalogo };
    let n = 0;
    conPendiente.forEach(([sku, a]) => {
      c[sku] = { ...a, costoVigente: a.promedioPendiente, promedioPendiente: null, ultimoEnvio: { fecha: hoy(), costo: a.promedioPendiente } };
      n++;
    });
    saveCatalogo(c);
    setAviso({ t: "ok", m: `${n} artículos actualizados en Zoho con su nuevo promedio.` });
  };

  return (
    <div className="space-y-4">
      <div className="flex flex-wrap items-center justify-between gap-2">
        <div>
          <h2 className="text-sm font-semibold">Catálogo de costos</h2>
          <p className="text-xs text-stone-500">El costo vigente es el que está en Zoho. El nuevo promedio se calcula al cerrar importaciones y se envía cuando tú lo apruebas.</p>
        </div>
        {conPendiente.length > 0 && (
          <button onClick={enviarTodos} className="px-3 py-2 bg-stone-900 text-white text-xs font-medium rounded hover:bg-stone-800">
            Actualizar {conPendiente.length} promedio{conPendiente.length > 1 ? "s" : ""} en Zoho
          </button>
        )}
      </div>

      <div className="flex flex-wrap items-center gap-2">
        <input value={busca} onChange={(e) => setBusca(e.target.value)} placeholder="Buscar SKU o artículo…"
          className="flex-1 min-w-[180px] px-3 py-2 text-sm bg-white border border-stone-300 rounded focus:outline-none focus:ring-2 focus:ring-teal-600" />
        <button onClick={() => setVerTodos((v) => !v)}
          className={`px-3 py-2 text-xs font-medium rounded border ${verTodos ? "bg-stone-900 text-white border-stone-900" : "bg-white text-stone-600 border-stone-300"}`}>
          {verTodos ? "Viendo todos" : "Solo importación"}
        </button>
        {rows.length > 200 && <span className="text-[11px] font-mono text-stone-500 w-full">Mostrando 200 de {rows.length} — usa el buscador para filtrar.</span>}
      </div>

      <div className="bg-white border border-stone-200 rounded-lg overflow-x-auto">
        <table className="w-full min-w-[820px] text-sm">
          <thead className="bg-stone-50 border-b border-stone-200">
            <tr className="text-[10px] uppercase tracking-widest text-stone-500">
              <th className="text-left px-3 py-2">SKU</th>
              <th className="text-left px-3 py-2">Artículo</th>
              <th className="text-right px-3 py-2">Exist.</th>
              <th className="text-right px-3 py-2 bg-teal-50">Promedio (Zoho)</th>
              <th className="text-right px-3 py-2">Última import.</th>
              <th className="text-right px-3 py-2 bg-amber-50">Nuevo promedio</th>
              <th className="text-right px-3 py-2">Δ</th>
              <th className="px-3 py-2"></th>
            </tr>
          </thead>
          <tbody>
            {rows.length === 0 && (
              <tr><td colSpan={8} className="px-3 py-8 text-center text-sm text-stone-500">
                {verTodos ? "Ningún artículo coincide con la búsqueda." : "Aún no has costeado artículos por la app. Activa \"Solo importación → Viendo todos\" para ver el catálogo completo."}
              </td></tr>
            )}
            {rows.slice(0, 200).map(([sku, a]) => {
              const pend = a.promedioPendiente != null;
              const delta = pend ? a.promedioPendiente - a.costoVigente : 0;
              const open = abierto === sku;
              const ult = a.historia?.length ? a.historia[a.historia.length - 1] : null;
              return (
                <Fragment key={sku}>
                  <tr className={`border-b border-stone-100 ${pend ? "bg-amber-50/40" : ""}`}>
                    <td className="px-3 py-2 font-mono text-xs font-semibold">{sku}</td>
                    <td className="px-3 py-2 text-stone-600 text-xs">{a.descripcion}</td>
                    <td className="px-3 py-2 text-right font-mono text-xs">{a.existencia ?? "—"}</td>
                    <td className="px-3 py-2 text-right font-mono bg-teal-50/50 font-semibold">${mx(a.costoVigente)}</td>
                    <td className="px-3 py-2 text-right font-mono text-xs text-stone-500">{ult ? `$${mx(ult.unitCost)}` : "—"}</td>
                    <td className="px-3 py-2 text-right font-mono bg-amber-50/60 font-semibold text-amber-800">{pend ? `$${mx(a.promedioPendiente)}` : "—"}</td>
                    <td className={`px-3 py-2 text-right font-mono text-xs ${delta > 0 ? "text-red-600" : delta < 0 ? "text-teal-700" : "text-stone-400"}`}>
                      {pend ? `${delta > 0 ? "+" : ""}${(delta / a.costoVigente * 100).toFixed(1)}%` : ""}
                    </td>
                    <td className="px-3 py-2 text-right whitespace-nowrap">
                      {a.historia?.length ? <button onClick={() => setAbierto(open ? null : sku)} className="px-2 py-1 text-[11px] text-stone-500 hover:text-stone-800">{open ? "▾ histórico" : "▸ histórico"}</button> : null}
                      {pend && <button onClick={() => enviarUno(sku)} className="px-2 py-1 text-[11px] font-medium text-teal-700 hover:bg-teal-50 rounded">Enviar a Zoho</button>}
                    </td>
                  </tr>
                  {open && (
                    <tr className="bg-stone-50/60">
                      <td colSpan={8} className="px-3 py-3">
                        <p className="text-[10px] uppercase tracking-widest text-stone-500 mb-2">Histórico de importaciones · {sku}</p>
                        {a.historia?.length ? (
                          <table className="w-full text-xs font-mono">
                            <thead><tr className="text-[10px] text-stone-400 uppercase"><th className="text-left py-1">Fecha</th><th className="text-left">Pedimento</th><th className="text-right">Pzas</th><th className="text-right">Costo landed</th><th className="text-right">Promedio resultante</th><th className="text-left pl-3">Estado</th></tr></thead>
                            <tbody>
                              {a.historia.map((h, i) => (
                                <tr key={i} className="border-t border-stone-200">
                                  <td className="py-1">{h.fecha}</td><td>{h.pedimento}</td>
                                  <td className="text-right">{h.qty}</td><td className="text-right">${mx(h.unitCost)}</td>
                                  <td className="text-right font-semibold">${mx(h.avgResult)}</td>
                                  <td className="pl-3 font-sans text-stone-500">{ESTADOS_DOC[h.estado] || h.estado}</td>
                                </tr>
                              ))}
                            </tbody>
                          </table>
                        ) : <p className="text-xs text-stone-400">Sin importaciones registradas en la app todavía. El costo vigente proviene de Zoho.</p>}
                        {a.ultimoEnvio && <p className="mt-2 text-[11px] text-stone-500">Último envío a Zoho: {a.ultimoEnvio.fecha} · ${mx(a.ultimoEnvio.costo)}</p>}
                      </td>
                    </tr>
                  )}
                </Fragment>
              );
            })}
          </tbody>
        </table>
      </div>
    </div>
  );
}

/* ===================== TAB 2 · IMPORTACIONES ===================== */
function Importaciones({ pedimentos, savePedimentos, catalogo, saveCatalogo, fletes, saveFletes, setAviso }) {
  const [modo, setModo] = useState("lista"); // lista | nueva | fletes | ped:<id>
  if (modo === "nueva")
    return <NuevaImportacion {...{ fletes, catalogo, onCancel: () => setModo("lista"), onSave: (p) => { savePedimentos([p, ...pedimentos]); setModo("lista"); setAviso({ t: "ok", m: `Pedimento ${p.numero} guardado como provisional.` }); } }} />;
  if (modo === "fletes")
    return (
      <div className="space-y-4">
        <button onClick={() => setModo("lista")} className="text-xs text-stone-500 hover:text-stone-800">← Volver a pedimentos</button>
        <Fletes fletes={fletes} saveFletes={saveFletes} />
      </div>
    );

  const ped = modo.startsWith("ped:") ? pedimentos.find((p) => p.id === modo.slice(4)) : null;
  if (ped)
    return <DetallePedimento {...{ ped, catalogo, saveCatalogo, pedimentos, savePedimentos, setAviso, onBack: () => setModo("lista") }} />;

  return (
    <div className="space-y-4">
      <div className="flex items-center justify-between">
        <h2 className="text-sm font-semibold">Pedimentos</h2>
        <div className="flex gap-2">
          <button onClick={() => setModo("fletes")} className="px-3 py-2 border border-stone-300 text-stone-600 text-xs font-medium rounded hover:bg-stone-50">Proveedores de flete</button>
          <button onClick={() => setModo("nueva")} className="px-3 py-2 bg-stone-900 text-white text-xs font-medium rounded hover:bg-stone-800">+ Nueva importación</button>
        </div>
      </div>
      {pedimentos.length === 0 ? (
        <div className="bg-white border border-stone-200 rounded-lg p-10 text-center text-sm text-stone-500">Aún no hay pedimentos capturados.</div>
      ) : (
        <div className="space-y-2">
          {pedimentos.map((p) => {
            const st = estadoPedimento(p);
            return (
              <button key={p.id} onClick={() => setModo("ped:" + p.id)} className="w-full bg-white border border-stone-200 rounded-lg px-4 py-3 flex flex-wrap items-center justify-between gap-2 hover:border-stone-400 text-left">
                <div className="flex items-center gap-3">
                  <span className="font-mono text-sm font-semibold">{p.numero}</span>
                  <span className="text-xs text-stone-500">{p.fecha}</span>
                  <EstadoBadge estado={st} />
                </div>
                <span className="font-mono text-xs text-stone-600">{p.partidas.length} partida{p.partidas.length > 1 ? "s" : ""} · TC {p.tc}</span>
              </button>
            );
          })}
        </div>
      )}
    </div>
  );
}

function estadoPedimento(p) {
  if (p.cerrado) return "cerrado";
  const inc = p.incrementables.filter((i) => i.monto > 0 || i.metodo === "manual");
  const todosFinal = inc.length > 0 && inc.every((i) => i.estadoDoc === "final");
  if (todosFinal) return "listo";
  const algunoFinal = inc.some((i) => i.estadoDoc === "final" || i.estadoDoc === "cotizacion");
  return algunoFinal ? "conciliacion" : "provisional";
}

function EstadoBadge({ estado }) {
  const map = {
    provisional: ["Provisional", "bg-amber-100 text-amber-800"],
    conciliacion: ["En conciliación", "bg-blue-100 text-blue-800"],
    listo: ["Listo para cerrar", "bg-teal-100 text-teal-800"],
    cerrado: ["Cerrado", "bg-stone-200 text-stone-700"],
  };
  const [t, c] = map[estado] || map.provisional;
  return <span className={`px-2 py-0.5 text-[10px] rounded font-medium ${c}`}>{t}</span>;
}

/* ---------- Motor de prorrateo ---------- */
function prorratear(partidas, incrementables, tc) {
  const ls = partidas.filter((p) => p.sku.trim() && +p.cantidad > 0).map((p) => {
    const cant = +p.cantidad || 0, fobU = +p.fobUnit || 0, peso = (+p.pesoKg || 0) * cant;
    return { ...p, cant, fobMXN: cant * fobU * tc, pesoTotal: peso };
  });
  const totV = ls.reduce((a, b) => a + b.fobMXN, 0), totP = ls.reduce((a, b) => a + b.pesoTotal, 0), totC = ls.reduce((a, b) => a + b.cant, 0);
  const asg = {}; ls.forEach((l) => (asg[l.id] = {}));
  let noCap = 0;
  incrementables.forEach((c) => {
    const bruto = +c.monto || 0;
    if (!bruto && c.metodo !== "manual") return;
    const mMXN = c.moneda === "USD" ? bruto * tc : bruto;
    if (!c.capitaliza) { noCap += mMXN; return; }
    if (c.metodo === "manual") { ls.forEach((l) => { const v = +(c.manual?.[l.id]) || 0; if (v) asg[l.id][c.concepto] = (asg[l.id][c.concepto] || 0) + v; }); return; }
    const base = c.metodo === "valor" ? totV : c.metodo === "peso" ? totP : c.metodo === "cantidad" ? totC : ls.length;
    if (!base) return;
    ls.forEach((l) => {
      const parte = c.metodo === "valor" ? l.fobMXN : c.metodo === "peso" ? l.pesoTotal : c.metodo === "cantidad" ? l.cant : 1;
      const v = (mMXN * parte) / base; if (v) asg[l.id][c.concepto] = (asg[l.id][c.concepto] || 0) + v;
    });
  });
  const lineas = ls.map((l) => {
    const incr = Object.values(asg[l.id]).reduce((a, b) => a + b, 0), total = l.fobMXN + incr;
    return { ...l, asig: asg[l.id], incr, total, unit: l.cant ? total / l.cant : 0 };
  });
  return { lineas, totV, totP, totC, noCap };
}

/* ---------- Nueva importación ---------- */
// Buscador de SKU con autocompletado: filtra por SKU o descripción y muestra SKU · descripción · precio
function SkuPicker({ value, onChange, catalogo, inp }) {
  const [q, setQ] = useState(value || "");
  const [open, setOpen] = useState(false);
  useEffect(() => { setQ(value || ""); }, [value]);
  const ql = q.trim().toLowerCase();
  const matches = ql
    ? Object.entries(catalogo).filter(([sku, a]) => sku.toLowerCase().includes(ql) || (a.descripcion || "").toLowerCase().includes(ql)).slice(0, 15)
    : [];
  return (
    <div className="relative max-w-[420px]">
      <input value={q} onChange={(e) => { const v = e.target.value.toUpperCase(); setQ(v); setOpen(true); onChange(v); }} onFocus={() => setOpen(true)} onBlur={() => setTimeout(() => setOpen(false), 180)}
        className={inp + " font-mono"} placeholder="Escribe SKU o descripción…" />
      {open && matches.length > 0 && (
        <div className="absolute z-20 mt-1 w-full max-h-60 overflow-y-auto bg-white border border-stone-300 rounded-lg shadow-lg">
          {matches.map(([sku, a]) => (
            <button key={sku} onMouseDown={(e) => { e.preventDefault(); onChange(sku); setQ(sku); setOpen(false); }}
              className="block w-full text-left px-3 py-1.5 hover:bg-teal-50 text-xs border-b border-stone-100 last:border-0">
              <span className="font-mono font-semibold">{sku}</span>
              <span className="text-stone-500"> · {a.descripcion}</span>
              <span className="text-stone-700 font-mono"> · ${mx0(a.costoVigente)}</span>
            </button>
          ))}
        </div>
      )}
    </div>
  );
}

// Vista de prorrateo detallado por SKU (formato del Excel del equipo) + exporte CSV
const csvCell = (v) => { const s = String(v ?? ""); return /[",\n;]/.test(s) ? '"' + s.replace(/"/g, '""') + '"' : s; };
function ProrrateoDetalle({ pedNumero, lineas, incs, tc, catalogo, setPartidas, proyecto = "MATERIAL PARA PROYECTOS" }) {
  const cols = incs.filter((c) => c.capitaliza && c.concepto).map((c) => c.concepto);
  const abrev = (c) => c.replace(/Flete internacional origen → San Diego/i, "FLETE CA-SD").replace(/Cruce San Diego → Tijuana/i, "CRUCE SD-TJ").replace(/Flete Tijuana → Los Cabos/i, "FLETE TJ-CSL").replace(/Cuenta de Gastos Americana \(ICC\)/i, "OTROS INCREM").replace(/Honorarios \+ servicios agente/i, "HON ADU").replace(/Prevalidación/i, "PRV").replace(/de importación/i, "");
  const rows = lineas.map((l) => {
    const fobUSD = (+l.fobUnit || 0) * l.cant;
    const cslUSD = tc ? l.unit / tc : 0;
    return { l, fobUSD, cslMXN: l.unit, cslUSD, difUSD: cslUSD - (+l.fobUnit || 0), pct: (+l.fobUnit || 0) ? (cslUSD - (+l.fobUnit || 0)) / (+l.fobUnit || 0) : 0 };
  });
  const exportar = () => {
    const head = ["NO. ORDEN", "CANT", "SKU", "ARTICULO", "EXW USD", "FOB USD", "IMPORTE MXN", ...cols.map(abrev), "TOTAL MXN", "COSTO CSL MXN", "COSTO CSL USD", "DIFERENCIA USD", "%", "PROYECTO"];
    const out = [head.map(csvCell).join(",")];
    rows.forEach(({ l, fobUSD, cslMXN, cslUSD, difUSD, pct }) => {
      out.push([l.oc || "", l.cant, l.sku, catalogo[l.sku]?.descripcion || l.desc, (+l.fobUnit || 0).toFixed(2), fobUSD.toFixed(2), l.fobMXN.toFixed(2), ...cols.map((c) => (l.asig[c] || 0).toFixed(2)), l.total.toFixed(2), cslMXN.toFixed(2), cslUSD.toFixed(2), difUSD.toFixed(2), (pct * 100).toFixed(2) + "%", proyecto].map(csvCell).join(","));
    });
    const blob = new Blob(["﻿" + out.join("\r\n")], { type: "text/csv;charset=utf-8;" });
    const url = URL.createObjectURL(blob);
    const a = document.createElement("a"); a.href = url; a.download = `Prorrateo ${pedNumero || "pedimento"}.csv`; a.click(); URL.revokeObjectURL(url);
  };
  if (!lineas.length) return <p className="p-4 text-xs text-stone-500">Asigna SKU y cantidades a las partidas para ver el prorrateo detallado.</p>;
  const th = "px-2 py-1.5 text-[10px] uppercase tracking-wide text-stone-500 whitespace-nowrap";
  const td = "px-2 py-1 font-mono text-right whitespace-nowrap";
  return (
    <div>
      <div className="flex items-center justify-between px-3 py-2">
        <p className="text-[11px] text-stone-500">Costo landed prorrateado por SKU (por valor FOB). El IVA no capitaliza. Edita la OC de cada renglón.</p>
        <button onClick={exportar} className="px-3 py-1.5 bg-stone-900 text-white text-xs font-medium rounded hover:bg-stone-800">Exportar CSV</button>
      </div>
      <div className="overflow-x-auto">
        <table className="min-w-[1100px] w-full text-xs">
          <thead className="bg-stone-50 border-y border-stone-200"><tr>
            <th className={th + " text-left"}>OC</th><th className={th + " text-right"}>Cant</th><th className={th + " text-left"}>SKU</th><th className={th + " text-left"}>Artículo</th>
            <th className={th + " text-right"}>EXW USD</th><th className={th + " text-right"}>FOB USD</th><th className={th + " text-right"}>Importe MXN</th>
            {cols.map((c) => <th key={c} className={th + " text-right"}>{abrev(c)}</th>)}
            <th className={th + " text-right"}>Total MXN</th><th className={th + " text-right bg-teal-50"}>CSL MXN</th><th className={th + " text-right bg-teal-50"}>CSL USD</th><th className={th + " text-right"}>Dif USD</th><th className={th + " text-right"}>%</th>
          </tr></thead>
          <tbody>
            {rows.map(({ l, fobUSD, cslMXN, cslUSD, difUSD, pct }) => (
              <tr key={l.id} className="border-b border-stone-100">
                <td className="px-2 py-1 w-20"><input value={l.oc || ""} onChange={(e) => setPartidas((s) => s.map((x) => (x.id === l.id ? { ...x, oc: e.target.value } : x)))} className="w-16 px-1 py-0.5 text-xs font-mono border border-stone-200 rounded" placeholder="—" /></td>
                <td className={td}>{l.cant}</td>
                <td className="px-2 py-1 font-mono text-left">{l.sku}</td>
                <td className="px-2 py-1 text-left text-stone-600 max-w-[220px] truncate">{catalogo[l.sku]?.descripcion || l.desc}</td>
                <td className={td}>{mx(+l.fobUnit || 0)}</td>
                <td className={td}>{mx(fobUSD)}</td>
                <td className={td}>{mx0(l.fobMXN)}</td>
                {cols.map((c) => <td key={c} className={td + " text-stone-500"}>{mx0(l.asig[c] || 0)}</td>)}
                <td className={td + " font-semibold"}>{mx0(l.total)}</td>
                <td className={td + " bg-teal-50/50 font-semibold"}>{mx0(cslMXN)}</td>
                <td className={td + " bg-teal-50/50"}>{mx(cslUSD)}</td>
                <td className={td + " text-stone-500"}>{mx(difUSD)}</td>
                <td className={td + " text-stone-500"}>{(pct * 100).toFixed(1)}%</td>
              </tr>
            ))}
          </tbody>
        </table>
      </div>
    </div>
  );
}

function NuevaImportacion({ fletes, catalogo, onCancel, onSave }) {
  const [ped, setPed] = useState({ numero: "", fecha: hoy(), tc: "", proveedorExt: "", ocZoho: "" });
  const [partidas, setPartidas] = useState([{ id: uid(), oc: "", sku: "", desc: "", categoria: "Batería", cantidad: "", fobUnit: "", pesoKg: "" }]);
  const [incs, setIncs] = useState(() => [
    ...fletes.filter((f) => f.incrementable).map((f) => ({ id: uid(), concepto: f.tramo, proveedor: f.proveedor, monto: f.tarifa, moneda: f.moneda, metodo: "valor", capitaliza: true, estadoDoc: f.tarifa ? "estimado" : "estimado", manual: {} })),
    ...CONCEPTOS_FIJOS.map((c) => ({ id: uid(), ...c, monto: "", estadoDoc: "estimado", manual: {} })),
    ...fletes.filter((f) => !f.incrementable).map((f) => ({ id: uid(), concepto: f.tramo, proveedor: f.proveedor, monto: f.tarifa, moneda: f.moneda, metodo: "valor", capitaliza: true, estadoDoc: "estimado", manual: {} })),
  ]);

  const [pdfPed, setPdfPed] = useState(null);
  const [pdfCot, setPdfCot] = useState(null);
  const [pdfFacturas, setPdfFacturas] = useState([]);   // facturas del proveedor (varias)
  const [extrayendo, setExtrayendo] = useState(false);
  const [errExtrac, setErrExtrac] = useState(null);
  const [extraido, setExtraido] = useState(false);
  const [adjuntos, setAdjuntos] = useState([]);
  const [empatando, setEmpatando] = useState(false);
  const [dudosos, setDudosos] = useState(null);   // null = modal cerrado; array = abierto
  const [empateMsg, setEmpateMsg] = useState(null);
  const [buscandoOC, setBuscandoOC] = useState(false);
  const [ocMsg, setOcMsg] = useState(null);
  const [guiaEmbarque, setGuiaEmbarque] = useState("");   // no. de contenedor/guía del embarque (identifica esta importación)
  const [pendPOs, setPendPOs] = useState([]);             // OC de Renon pendientes por surtir (para el datalist)

  const tc = +ped.tc || 0;
  const calc = useMemo(() => prorratear(partidas, incs, tc), [partidas, incs, tc]);
  const inp = "w-full px-2 py-1.5 text-sm bg-white border border-stone-300 rounded focus:outline-none focus:ring-2 focus:ring-teal-600";
  const upd = (setter) => (id, k, v) => setter((s) => s.map((x) => (x.id === id ? { ...x, [k]: v } : x)));

  const setInc = (match, campo, valor, estadoDoc) =>
    setIncs((s) => s.map((x) => (x.concepto.toLowerCase().includes(match) ? { ...x, [campo]: valor, ...(estadoDoc ? { estadoDoc } : {}) } : x)));
  // Vuelca varios campos a la vez (p. ej. monto + moneda) al renglón que coincide
  const setIncFull = (match, patch, estadoDoc) =>
    setIncs((s) => s.map((x) => (x.concepto.toLowerCase().includes(match) ? { ...x, ...patch, ...(estadoDoc ? { estadoDoc } : {}) } : x)));

  // Asigna un SKU a una partida y jala su categoría del catálogo
  const asignarSku = (partId, sku) => {
    const known = catalogo[sku];
    setPartidas((s) => s.map((x) => (x.id === partId ? { ...x, sku, ...(known ? { categoria: known.categoria } : {}) } : x)));
  };

  // Empata cada partida contra el catálogo (sincronizado de Books) usando IA.
  // Los de alta confianza (>=0.8) se asignan solos; los dudosos abren el popup.
  const empatarSkus = async () => {
    setEmpateMsg(null);
    const conCant = partidas.filter((p) => +p.cantidad > 0 && (p.desc || "").trim());
    if (!conCant.length) return setErrExtrac("Captura al menos una partida con descripción y cantidad antes de asignar SKUs.");
    const cats = new Set(conCant.map((p) => p.categoria));
    let cands = Object.entries(catalogo).filter(([, a]) => cats.has(a.categoria)).map(([sku, a]) => ({ sku, desc: a.descripcion, costo: Math.round(a.costoVigente || 0) }));
    if (!cands.length) cands = Object.entries(catalogo).map(([sku, a]) => ({ sku, desc: a.descripcion, costo: Math.round(a.costoVigente || 0) }));
    // Si hay demasiados candidatos, deja los más relevantes por palabras clave (tope de tokens)
    if (cands.length > 400) {
      const kw = conCant.map((p) => (p.desc || "").toLowerCase()).join(" ");
      const tokens = [...new Set(kw.split(/[^a-z0-9]+/i).filter((t) => t.length > 3))];
      const score = (d) => tokens.reduce((a, t) => a + ((d || "").toLowerCase().includes(t) ? 1 : 0), 0);
      cands = cands.sort((a, b) => score(b.desc) - score(a.desc)).slice(0, 400);
    }
    setEmpatando(true); setErrExtrac(null);
    try {
      // Costo unitario aprox de cada partida en MXN (FOB × TC) para desempatar por precio
      const lista = conCant.map((p, i) => ({ i, desc: p.desc, cant: +p.cantidad || 0, costoUnitAproxMXN: Math.round((+p.fobUnit || 0) * tc) }));
      const prompt = `Eres experto en catálogos de importación de equipo de energía solar y baterías. Identifica, para cada PARTIDA de un pedimento, el SKU del CATÁLOGO que corresponde al MISMO producto.\n\nTienes:\n(A) PARTIDAS del pedimento (descripción aduanal genérica + costo unitario aproximado en MXN).\n(B) CATÁLOGO con SKU, descripción comercial y su costo (MXN).\n(C) Si vienen adjuntas, las FACTURAS del proveedor (Renon): tráelas como fuente principal — ahí está el modelo/nombre real de cada equipo, que la descripción aduanal no dice. Cruza la factura con la partida por cantidad y precio.\n\nReglas de empate:\n- Fíjate en modelos y capacidades: "XTREME HV", "LV 1.0", "5KW", marcas, etc.\n- Usa el COSTO como desempate: el costoUnitAproxMXN de la partida debe parecerse al costo del SKU del catálogo. Si un candidato tiene un costo muy distinto, baja la confianza.\n- OJO: una partida puede ser un SISTEMA/kit (módulo de control + varias baterías). Si es así y existe un SKU que representa el sistema completo, elígelo; si no, escoge el más cercano y baja la confianza.\n\nResponde SOLO JSON compacto, sin markdown:\n{"asignaciones":[{"i":0,"sku":"","confianza":0,"alternativas":["",""]}]}\n- i = índice de la partida (empieza en 0).\n- sku = el SKU del catálogo más probable, EXACTO como viene. Si ninguno encaja, sku="" y confianza=0.\n- confianza = 0 a 1 (1 = segurísimo).\n- alternativas = hasta 3 SKU candidatos alternos por si el usuario corrige.\nUsa únicamente SKU que existan en el catálogo. Solo el JSON.\n\nPARTIDAS:\n${JSON.stringify(lista)}\n\nCATÁLOGO:\n${JSON.stringify(cands)}`;
      const mContent = pdfFacturas.map((b) => ({ type: "document", source: { type: "base64", media_type: "application/pdf", data: b } }));
      mContent.push({ type: "text", text: prompt });
      const data = await window.aiExtract({ model: "claude-sonnet-5", max_tokens: 3000, messages: [{ role: "user", content: mContent }] });
      if (data && (data.error || data.type === "error")) throw new Error("Anthropic: " + (data.error?.message || JSON.stringify(data.error)));
      const txt = (data.content || []).filter((i) => i.type === "text").map((i) => i.text).join("").replace(/```json|```/g, "").trim();
      if (!txt) throw new Error("la IA no devolvió texto (motivo: " + (data.stop_reason || "desconocido") + ")");
      const res = extraerJSON(txt);
      const asg = Array.isArray(res.asignaciones) ? res.asignaciones : [];
      const pend = []; let autos = 0;
      conCant.forEach((part, i) => {
        const a = asg.find((x) => x.i === i);
        const ok = a && a.sku && catalogo[a.sku];
        if (ok && (a.confianza ?? 0) >= 0.8) { asignarSku(part.id, a.sku); autos++; }
        else pend.push({ id: part.id, desc: part.desc, cantidad: part.cantidad, costoAprox: Math.round((+part.fobUnit || 0) * tc), confianza: a?.confianza ?? 0, alternativas: (a?.alternativas || []).filter((s) => catalogo[s]), chosen: ok ? a.sku : "" });
      });
      if (pend.length) setDudosos(pend);
      setEmpateMsg(`${autos} SKU asignado${autos === 1 ? "" : "s"} automáticamente${pend.length ? ` · ${pend.length} por confirmar` : " · todo listo"}.`);
    } catch (e) {
      setErrExtrac("No se pudieron asignar los SKU automáticamente: " + (e.message || e) + ". Puedes asignarlos a mano.");
    }
    setEmpatando(false);
  };

  // Desglosa las facturas del proveedor en un renglón POR LÍNEA de factura (los kits se
  // abren en sus componentes: batería + módulo de control), cada uno empatado a un SKU.
  // REEMPLAZA la lista de partidas por el desglose a nivel componente.
  const desglosarPorFactura = async () => {
    setEmpateMsg(null);
    if (!pdfFacturas.length) return setErrExtrac("Sube al menos una factura del proveedor (sección de arriba) para desglosar.");
    // Candidatos relevantes: baterías + controles/racks/sistemas Renon
    const rel = (d) => /(renon|ecube|xtreme|xcellent|control|rack|m[oó]dulo|bater)/i.test(d || "");
    const cands = Object.entries(catalogo).filter(([, a]) => a.categoria === "Batería" || rel(a.descripcion)).map(([sku, a]) => ({ sku, desc: a.descripcion, costo: Math.round(a.costoVigente || 0) }));
    setEmpatando(true); setErrExtrac(null);
    try {
      const allLineas = [];
      let guiaDetectada = "";
      for (let k = 0; k < pdfFacturas.length; k++) {
        const prompt = `Lee esta FACTURA (commercial invoice / packing list) del proveedor Renon. Devuelve SOLO JSON compacto, sin markdown:\n{"factura":"","guia":"","lineas":[{"modelo":"","desc":"","cantidad":0,"fobUnitUSD":0,"pesoUnitKg":0,"sku":"","confianza":0,"alternativas":["",""]}]}\n- factura = el número de factura / "Contract No" de la factura (ej. RN-26012201JFA).\n- guia = el número de contenedor / marca de embarque (columna "Marks&Ctn.No." o similar, ej. EMCUUH3864), si aparece; si no, "".\n- Una línea por CADA renglón de mercancía de la factura (columna Description / Quantity / Unit price). Incluye TODOS los renglones (ej. batería y módulo de control por separado).\n- modelo = OBLIGATORIO: el código de la columna "Mark & No" del renglón, que empieza con R- (ej. R-EM096050-XTH01, R-MC050-XTH01, R-XC016161-H-US, R-EC060LCB02-US). NO uses la descripción genérica ("energy storage system", "lithium ion batteries") como modelo — usa SIEMPRE ese código R-.\n- cantidad = las PCS de ese renglón. fobUnitUSD = Unit price en USD. pesoUnitKg = N.W.(KG) de ese renglón ÷ cantidad (0 si no aparece).\n- sku = empata por el código de modelo Y por costo (fobUnitUSD×17.37 debe parecerse al costo del SKU): XTH=batería Extreme HV / XTL=batería Extreme LV / MC…-XTH=control HV / MC…-XTL=control LV / XC016=Xcellent / EC060=ECube 60. Si el costo de un candidato es MUY distinto al fobUnitUSD×17.37, NO lo elijas. Si ninguno encaja, sku="" y confianza=0.\n- confianza = 0 a 1. alternativas = hasta 3 SKU candidatos ordenados por cercanía de costo. Usa solo SKU que existan en el catálogo. Solo el JSON.\n\nCATÁLOGO:\n${JSON.stringify(cands)}`;
        const content = [{ type: "document", source: { type: "base64", media_type: "application/pdf", data: pdfFacturas[k] } }, { type: "text", text: prompt }];
        const data = await window.aiExtract({ model: "claude-sonnet-5", max_tokens: 4000, messages: [{ role: "user", content }] });
        if (data && (data.error || data.type === "error")) throw new Error("Anthropic: " + (data.error?.message || JSON.stringify(data.error)));
        const txt = (data.content || []).filter((i) => i.type === "text").map((i) => i.text).join("").replace(/```json|```/g, "").trim();
        if (!txt) throw new Error("factura " + (k + 1) + ": la IA no devolvió texto (motivo: " + (data.stop_reason || "desconocido") + ")");
        const res = extraerJSON(txt);
        const fact = (res.factura || "").trim() || `Factura ${k + 1}`;
        if (!guiaDetectada && (res.guia || "").trim()) guiaDetectada = (res.guia || "").trim();
        if (Array.isArray(res.lineas)) res.lineas.forEach((l) => allLineas.push({ ...l, _factura: fact }));
      }
      if (guiaDetectada) setGuiaEmbarque(guiaDetectada);
      if (!allLineas.length) throw new Error("no se encontraron renglones en las facturas.");
      const nuevas = allLineas.map((l) => {
        // Empate determinístico por código de modelo Renon; si no, lo que dijo la IA
        const forzado = matchRenonSku(l.modelo, l.desc);
        const skuOk = forzado && catalogo[forzado] ? forzado : (l.sku && catalogo[l.sku] ? l.sku : "");
        const conf = forzado ? 0.96 : (l.confianza ?? 0);
        return { id: uid(), oc: "", factura: l._factura || "", sku: skuOk, desc: l.desc || l.modelo || "", categoria: catalogo[skuOk]?.categoria || adivinaCategoria(l.desc || l.modelo || ""), cantidad: l.cantidad || "", fobUnit: l.fobUnitUSD || "", pesoKg: l.pesoUnitKg || "", _conf: conf, _alt: (l.alternativas || []).filter((s) => catalogo[s]) };
      });
      setPartidas(nuevas.map(({ _conf, _alt, ...p }) => p));
      const pend = nuevas.filter((p) => !p.sku || (p._conf ?? 0) < 0.8).map((p) => ({ id: p.id, desc: p.desc, cantidad: p.cantidad, costoAprox: Math.round((+p.fobUnit || 0) * tc), confianza: p._conf ?? 0, alternativas: p._alt, chosen: p.sku || "" }));
      if (pend.length) setDudosos(pend);
      setEmpateMsg(`${nuevas.length} renglón${nuevas.length === 1 ? "" : "es"} de factura · ${nuevas.length - pend.length} con SKU · ${pend.length} por confirmar.`);
    } catch (e) {
      setErrExtrac("No se pudo desglosar la factura: " + (e.message || e) + ". Puedes capturar los renglones a mano.");
    }
    setEmpatando(false);
  };

  // Agrupa los renglones por factura (para ligar cada factura a su orden de compra)
  const gruposFactura = useMemo(() => {
    const m = {};
    partidas.forEach((p) => {
      if (!p.factura) return;
      if (!m[p.factura]) m[p.factura] = { factura: p.factura, qty: 0, fobUSD: 0, oc: "", ids: [] };
      m[p.factura].qty += +p.cantidad || 0;
      m[p.factura].fobUSD += (+p.fobUnit || 0) * (+p.cantidad || 0);
      m[p.factura].ids.push(p.id);
      if (p.oc) m[p.factura].oc = p.oc;
    });
    return Object.values(m);
  }, [partidas]);

  const setOcGrupo = (ids, oc) => setPartidas((s) => s.map((x) => (ids.includes(x.id) ? { ...x, oc } : x)));

  // Busca las OC de Renon PENDIENTES POR SURTIR y propone una (estimada) por factura.
  // El admin confirma/cambia a mano — no se fuerza el cuadre, solo se sugiere.
  const buscarOCs = async () => {
    if (!gruposFactura.length) return setOcMsg("Primero desglosa por factura para tener los renglones agrupados.");
    if (typeof window.zohoBooks !== "function") return setOcMsg("La conexión a Books no está disponible en esta versión.");
    setBuscandoOC(true); setOcMsg("Buscando OC de Renon pendientes por surtir…");
    try {
      const data = await window.zohoBooks({ action: "list_purchase_orders", params: { vendor_name_contains: "RENON", filter_by: "Status.All", per_page: "100", sort_column: "date", sort_order: "D" } });
      // Solo las PENDIENTES POR SURTIR (algo por recibir), del proveedor
      const pend = (data.purchaseorders || []).filter((po) => (+po.quantity_yet_to_receive || 0) > 0 || (po.received_status && po.received_status !== "received")).map((po) => ({ id: po.purchaseorder_id, num: po.purchaseorder_number, guia: (po.cf_numero_de_gu_a_frontera || "").toUpperCase() }));
      setPendPOs(pend.map((p) => p.num));
      if (!pend.length) { setOcMsg("No hay OC de Renon pendientes por surtir. Captura la OC a mano."); setBuscandoOC(false); return; }
      // SKU -> cantidad de cada factura
      const grupos = [...gruposFactura].sort((a, b) => b.fobUSD - a.fobUSD);
      const skusGrupo = {};
      grupos.forEach((g) => { const m = {}; partidas.forEach((p) => { if (g.ids.includes(p.id) && p.sku) m[p.sku.toUpperCase()] = (m[p.sku.toUpperCase()] || 0) + (+p.cantidad || 0); }); skusGrupo[g.factura] = m; });
      // Lee los renglones de las OC pendientes (cache), para pre-sugerir por SKU/guía
      const detalle = {};
      const lineasDe = async (po) => { if (detalle[po.id]) return detalle[po.id]; try { const d = await window.zohoBooks({ action: "get_purchase_order", params: { purchaseorder_id: po.id } }); detalle[po.id] = (d.purchaseorder?.line_items || []).map((li) => ({ sku: (li.sku || "").toUpperCase(), qty: +li.quantity || 0 })); } catch (_) { detalle[po.id] = []; } return detalle[po.id]; };
      const gg = (guiaEmbarque || "").toUpperCase();
      const usadas = new Set(); let sugeridas = 0;
      for (const g of grupos) {
        const m = skusGrupo[g.factura]; const skus = Object.keys(m);
        if (!skus.length) continue;
        let best = null, bestScore = 0;
        for (const po of pend.filter((x) => !usadas.has(x.num))) {
          const items = await lineasDe(po);
          let score = 0;
          // surtido parcial: basta que el SKU esté en la OC con cantidad ordenada >= la de la factura
          skus.forEach((sku) => { const it = items.find((x) => x.sku === sku); if (it) score += (m[sku] <= it.qty ? 2 : 1); });
          if (skus.every((sku) => items.some((x) => x.sku === sku))) score += 5; // la OC contiene TODOS los equipos de la factura
          if (gg && po.guia && po.guia.includes(gg)) score += 10;               // misma guía/contenedor = esta importación
          if (score > bestScore) { bestScore = score; best = po; }
        }
        if (best && bestScore >= 2) { usadas.add(best.num); setOcGrupo(g.ids, best.num); sugeridas++; }
      }
      setOcMsg(`${pend.length} OC de Renon pendientes por surtir · ${sugeridas} propuestas (estimadas${gg ? " por guía/equipos" : " por equipos"}). Confírmalas o cámbialas a mano.`);
    } catch (e) {
      setOcMsg("No se pudo leer Books: " + (e.message || e));
    }
    setBuscandoOC(false);
  };

  const extraer = async () => {
    if (!pdfPed) return setErrExtrac("Sube al menos el PDF del pedimento.");
    setExtrayendo(true); setErrExtrac(null);
    try {
      const content = [{ type: "document", source: { type: "base64", media_type: "application/pdf", data: pdfPed } }];
      if (pdfCot) content.push({ type: "document", source: { type: "base64", media_type: "application/pdf", data: pdfCot } });
      content.push({ type: "text", text: PROMPT_EXTRACCION });
      const data = await window.aiExtract({ model: "claude-sonnet-5", max_tokens: 16000, messages: [{ role: "user", content }] });
      if (data && (data.error || data.type === "error")) throw new Error("Anthropic: " + (data.error?.message || JSON.stringify(data.error)));
      const txt = (data.content || []).filter((i) => i.type === "text").map((i) => i.text).join("").replace(/```json|```/g, "").trim();
      if (!txt) throw new Error("la IA no devolvió texto (motivo: " + (data.stop_reason || "desconocido") + ")");
      const p = extraerJSON(txt);

      setPed((old) => ({ ...old, numero: p.numero || old.numero, fecha: p.fecha || old.fecha, tc: p.tc || old.tc, aduana: p.aduana || "", proveedorExt: p.proveedorExt || old.proveedorExt }));

      if (Array.isArray(p.partidas) && p.partidas.length) {
        setPartidas(p.partidas.map((x) => ({ id: uid(), sku: "", desc: x.desc || "", categoria: adivinaCategoria(x.desc), cantidad: x.cantidad || "", fobUnit: x.fobUnitUSD || "", pesoKg: x.pesoUnitKg || "", _igi: x.igiMXN || 0 })));
      }

      // Volcar incrementables leídos a sus renglones (el flete internacional y el ICC del pedimento SIEMPRE son pesos)
      if (p.fleteInternacionalMXN != null) setIncFull("internacional", { monto: p.fleteInternacionalMXN, moneda: "MXN" }, "final");
      if (p.cruceSDTJusd != null) setIncFull("cruce", { monto: p.cruceSDTJusd, moneda: "USD" }, "final");
      if (p.dtaMXN != null) setInc("dta", "monto", p.dtaMXN, "final");
      if (p.prvMXN != null) setInc("prevalidación", "monto", p.prvMXN, "final");
      if (p.ivaMXN != null) setInc("iva", "monto", p.ivaMXN, "final");
      if (p.iccMXN != null) setIncFull("icc", { monto: p.iccMXN, moneda: "MXN" }, "final");
      if (p.honorariosMXN != null) setInc("honorarios", "monto", p.honorariosMXN, p.honorariosMXN ? "cotizacion" : "estimado");

      // IGI manual por partida (se asigna tras recrear partidas)
      if (Array.isArray(p.partidas)) {
        setTimeout(() => {
          setPartidas((parts) => {
            setIncs((s) => s.map((x) => {
              if (!x.concepto.toLowerCase().includes("igi")) return x;
              const manual = {};
              parts.forEach((pt) => { if (pt._igi) manual[pt.id] = pt._igi; });
              return { ...x, manual, estadoDoc: "final" };
            }));
            return parts;
          });
        }, 0);
      }

      setExtraido(true);
    } catch (e) {
      setErrExtrac("No se pudo leer el PDF automáticamente: " + (e.message || e) + ". Puedes capturar a mano abajo.");
    }
    setExtrayendo(false);
  };

  // OCs que amparan la importación (únicas, de todos los renglones)
  const ocsAmparan = [...new Set(partidas.map((p) => (p.oc || "").trim()).filter(Boolean))];
  // Falta OC si hay facturas agrupadas sin OC, o si no hay ninguna OC capturada
  const faltanOC = gruposFactura.length ? gruposFactura.some((g) => !(g.oc || "").trim()) : ocsAmparan.length === 0;

  const guardar = () => {
    if (!ped.numero.trim() || !tc || !calc.lineas.length || faltanOC) return;
    onSave({ id: uid(), ...ped, ocsAmparan, tc, partidas, incrementables: incs.map((i) => ({ ...i, monto: +i.monto || 0 })), adjuntos, cerrado: false, provisional: calc.lineas.map((l) => ({ sku: l.sku, qty: l.cant, unit: l.unit })) });
  };

  // Embarque mixto solo importa si HAY IGI que capturar (categorías con IGI distinto)
  const hayIGI = incs.some((c) => /igi/i.test(c.concepto) && ((+c.monto || 0) > 0 || Object.values(c.manual || {}).some((v) => +v > 0)));
  const mixto = hayIGI && new Set(calc.lineas.map((l) => l.categoria)).size > 1;

  return (
    <div className="space-y-4">
      {dudosos && (
        <div className="fixed inset-0 bg-black/40 flex items-center justify-center z-50 p-4" onClick={() => setDudosos(null)}>
          <div className="bg-white rounded-xl max-w-2xl w-full max-h-[85vh] overflow-y-auto p-5" onClick={(e) => e.stopPropagation()}>
            <h3 className="text-sm font-semibold mb-1">Confirma los SKU dudosos</h3>
            <p className="text-xs text-stone-500 mb-4">La app asignó sola los que tuvo claros. Estos necesitan tu confirmación — revisa o corrige el SKU de cada uno. Escribe para buscar en tu catálogo.</p>
            <div className="space-y-3">
              {dudosos.map((d, idx) => (
                <div key={d.id} className="border border-stone-200 rounded-lg p-3">
                  <p className="text-[10px] uppercase tracking-widest text-stone-400">Partida · confianza IA {Math.round((d.confianza || 0) * 100)}%</p>
                  <p className="text-sm mb-1">{d.desc}</p>
                  <p className="text-[11px] text-stone-500 mb-2">Cantidad: <span className="font-mono">{d.cantidad || "—"}</span> · Costo aprox. unitario: <span className="font-mono">${mx0(d.costoAprox)}</span> MXN</p>
                  <div className="flex items-start gap-2 flex-wrap">
                    <SkuPicker value={d.chosen} onChange={(v) => setDudosos((s) => s.map((x, j) => (j === idx ? { ...x, chosen: v } : x)))} catalogo={catalogo} inp={inp} />
                    {d.chosen && !catalogo[d.chosen] && <span className="text-[11px] text-red-600 mt-2">SKU no está en el catálogo</span>}
                  </div>
                  {d.alternativas.length > 0 && (
                    <div className="mt-2 flex items-center gap-1.5 flex-wrap">
                      <span className="text-[10px] uppercase tracking-widest text-stone-400">Sugerencias:</span>
                      {d.alternativas.map((s) => (
                        <button key={s} onClick={() => setDudosos((st) => st.map((x, j) => (j === idx ? { ...x, chosen: s } : x)))} className={`px-2 py-0.5 text-[11px] rounded border ${d.chosen === s ? "bg-teal-700 text-white border-teal-700" : "border-stone-300 text-stone-600 hover:bg-stone-50"}`}>{s}{catalogo[s] ? ` · $${mx0(catalogo[s].costoVigente)}` : ""}</button>
                      ))}
                    </div>
                  )}
                  {!d.chosen && <p className="mt-1 text-[11px] text-amber-700">La IA no encontró un SKU claro. Búscalo tú.</p>}
                </div>
              ))}
            </div>
            <div className="flex justify-end gap-2 mt-5">
              <button onClick={() => setDudosos(null)} className="px-3 py-2 text-xs text-stone-500 hover:text-stone-800">Cancelar</button>
              <button onClick={() => { dudosos.forEach((d) => { if (d.chosen && catalogo[d.chosen]) asignarSku(d.id, d.chosen); }); setDudosos(null); }} className="px-4 py-2 bg-stone-900 text-white text-xs font-medium rounded hover:bg-stone-800">Aplicar SKUs</button>
            </div>
          </div>
        </div>
      )}
      <div className="flex items-center justify-between">
        <h2 className="text-sm font-semibold">Nueva importación</h2>
        <button onClick={onCancel} className="text-xs text-stone-500 hover:text-stone-800">← Volver</button>
      </div>

      <Section n="0" t="Cargar PDFs (llenado automático)">
        <div className="p-4 space-y-3">
          <p className="text-xs text-stone-500">Sube el pedimento y, si la tienes, la cotización de Perezgrovas. La app extrae los datos y llena el formulario para que solo lo revises. El flete Tijuana→Cabo y cualquier extra los capturas tú abajo.</p>
          <div className="grid grid-cols-1 md:grid-cols-2 gap-3">
            <div>
              <Lbl>Pedimento (PDF)</Lbl>
              <input type="file" accept="application/pdf" onChange={async (e) => { const f = e.target.files?.[0]; if (f) { setPdfPed(await fileToB64(f)); setErrExtrac(null); } }}
                className="block w-full text-xs text-stone-600 file:mr-2 file:py-1.5 file:px-3 file:rounded file:border-0 file:text-xs file:font-medium file:bg-stone-900 file:text-white" />
              {pdfPed && <p className="mt-1 text-[11px] text-teal-700">✓ Pedimento cargado</p>}
            </div>
            <div>
              <Lbl>Cotización Perezgrovas (PDF, opcional)</Lbl>
              <input type="file" accept="application/pdf" onChange={async (e) => { const f = e.target.files?.[0]; if (f) { setPdfCot(await fileToB64(f)); setErrExtrac(null); } }}
                className="block w-full text-xs text-stone-600 file:mr-2 file:py-1.5 file:px-3 file:rounded file:border-0 file:text-xs file:font-medium file:bg-stone-900 file:text-white" />
              {pdfCot && <p className="mt-1 text-[11px] text-teal-700">✓ Cotización cargada</p>}
            </div>
            <div className="md:col-span-2">
              <Lbl>Facturas del proveedor (PDF, opcional · varias)</Lbl>
              <input type="file" accept="application/pdf" multiple onChange={async (e) => { const fs = Array.from(e.target.files || []); if (fs.length) { const b64s = await Promise.all(fs.map(fileToB64)); setPdfFacturas((s) => [...s, ...b64s]); setErrExtrac(null); } e.target.value = ""; }}
                className="block w-full text-xs text-stone-600 file:mr-2 file:py-1.5 file:px-3 file:rounded file:border-0 file:text-xs file:font-medium file:bg-stone-900 file:text-white" />
              {pdfFacturas.length > 0 && <p className="mt-1 text-[11px] text-teal-700">✓ {pdfFacturas.length} factura{pdfFacturas.length > 1 ? "s" : ""} cargada{pdfFacturas.length > 1 ? "s" : ""} <button onClick={() => setPdfFacturas([])} className="ml-1 text-stone-400 hover:text-red-600">(quitar)</button></p>}
              <p className="mt-1 text-[10px] text-stone-400">Las facturas del proveedor (Renon) traen el modelo real de cada equipo — sirven para que la app empate mejor los SKU.</p>
            </div>
          </div>
          <div className="flex items-center gap-3">
            <button onClick={extraer} disabled={!pdfPed || extrayendo}
              className="px-4 py-2 bg-teal-700 text-white text-sm font-medium rounded hover:bg-teal-800 disabled:opacity-40">
              {extrayendo ? "Leyendo PDF…" : "Extraer datos"}
            </button>
            {extraido && !errExtrac && <span className="text-xs text-teal-700">✓ Datos extraídos. Revísalos abajo antes de guardar.</span>}
          </div>
          {errExtrac && <div className="px-3 py-2 rounded text-xs bg-amber-50 border border-amber-300 text-amber-900">{errExtrac}</div>}
          {extraido && <div className="px-3 py-2 rounded text-xs bg-blue-50 border border-blue-200 text-blue-900">⚠ La lectura automática puede tener errores, sobre todo en pedimentos de varias hojas. <strong>Verifica cada partida, el IGI y los montos</strong> contra el PDF antes de guardar.</div>}
        </div>
      </Section>

      <Section n="1" t="Pedimento">
        <div className="p-4 grid grid-cols-2 md:grid-cols-4 gap-3">
          <Field l="Número"><input className={inp + " font-mono"} value={ped.numero} onChange={(e) => setPed({ ...ped, numero: e.target.value })} placeholder="26 40 3965 …" /></Field>
          <Field l="Fecha de pago"><input type="date" className={inp} value={ped.fecha} onChange={(e) => setPed({ ...ped, fecha: e.target.value })} /></Field>
          <Field l="Tipo de cambio"><input type="number" step="0.0001" className={inp + " font-mono"} value={ped.tc} onChange={(e) => setPed({ ...ped, tc: e.target.value })} placeholder="17.4030" /></Field>
          <Field l="OC(s) en Zoho que amparan"><input className={inp + " font-mono bg-stone-50 text-stone-600"} value={ocsAmparan.join(", ")} readOnly placeholder="Se cargan en la sección 2b (una por factura)" /></Field>
        </div>
      </Section>

      <Section n="2" t="Mercancía — valor FOB" r={`FOB $${mx0(calc.totV)} · ${mx0(calc.totP)} kg`}>
        <div className="overflow-x-auto">
          <table className="w-full min-w-[860px]">
            <thead className="bg-stone-50 border-y border-stone-200"><tr className="text-[10px] uppercase tracking-widest text-stone-500">
              <th className="text-left px-2 py-2">SKU</th><th className="text-left px-2 py-2">Desc. en pedimento</th><th className="text-left px-2 py-2">Desc. en Books</th><th className="text-left px-2 py-2">Tipo</th>
              <th className="text-right px-2 py-2">Cant.</th><th className="text-right px-2 py-2">FOB u. USD</th><th className="text-right px-2 py-2">Peso u. kg</th><th></th>
            </tr></thead>
            <tbody>
              {partidas.map((p) => (
                <tr key={p.id} className="border-b border-stone-100">
                  <td className="px-2 py-1.5 w-32">
                    <input list="skus" className={inp + " font-mono"} value={p.sku} onChange={(e) => { const v = e.target.value.toUpperCase(); const known = catalogo[v]; upd(setPartidas)(p.id, "sku", v); if (known) { upd(setPartidas)(p.id, "categoria", known.categoria); } }} />
                  </td>
                  <td className="px-2 py-1.5"><input className={inp} value={p.desc} onChange={(e) => upd(setPartidas)(p.id, "desc", e.target.value)} /></td>
                  <td className="px-2 py-1.5 text-xs text-stone-500 max-w-[200px] truncate">{catalogo[p.sku]?.descripcion || <span className="text-stone-300">—</span>}</td>
                  <td className="px-2 py-1.5 w-28"><select className={inp} value={p.categoria} onChange={(e) => upd(setPartidas)(p.id, "categoria", e.target.value)}>{CATS.map((c) => <option key={c}>{c}</option>)}</select></td>
                  <td className="px-2 py-1.5 w-20"><input type="number" className={inp + " font-mono text-right"} value={p.cantidad} onChange={(e) => upd(setPartidas)(p.id, "cantidad", e.target.value)} /></td>
                  <td className="px-2 py-1.5 w-28"><input type="number" step="0.01" className={inp + " font-mono text-right"} value={p.fobUnit} onChange={(e) => upd(setPartidas)(p.id, "fobUnit", e.target.value)} /></td>
                  <td className="px-2 py-1.5 w-24"><input type="number" step="0.01" className={inp + " font-mono text-right"} value={p.pesoKg} onChange={(e) => upd(setPartidas)(p.id, "pesoKg", e.target.value)} /></td>
                  <td className="px-2 w-8"><button onClick={() => setPartidas((s) => (s.length > 1 ? s.filter((x) => x.id !== p.id) : s))} className="text-stone-400 hover:text-red-600 text-lg">×</button></td>
                </tr>
              ))}
            </tbody>
          </table>
          <datalist id="skus">{Object.keys(catalogo).map((s) => <option key={s} value={s} />)}</datalist>
        </div>
        <div className="p-4 space-y-2 border-t border-stone-200 bg-stone-50/60">
          <div className="flex items-center gap-3 flex-wrap">
            <button onClick={desglosarPorFactura} disabled={empatando || !pdfFacturas.length}
              className="px-5 py-2.5 bg-teal-700 text-white text-sm font-semibold rounded-lg hover:bg-teal-800 disabled:opacity-40 shadow-sm"
              title={pdfFacturas.length ? "Flujo normal: abre los kits en sus componentes usando las facturas" : "Sube facturas del proveedor arriba para habilitar"}>
              {empatando ? "Procesando…" : "🧩 Desglosar por factura"}<span className="ml-1 text-teal-100 font-normal text-xs">· recomendado</span>
            </button>
            <button onClick={empatarSkus} disabled={empatando}
              className="px-4 py-2.5 border border-stone-300 text-stone-700 text-sm font-medium rounded-lg hover:bg-white disabled:opacity-40">
              {empatando ? "Procesando…" : "🎯 Auto-asignar SKUs"}
            </button>
            <button onClick={() => setPartidas((s) => [...s, { id: uid(), oc: "", sku: "", desc: "", categoria: "Batería", cantidad: "", fobUnit: "", pesoKg: "" }])} className="text-xs font-medium text-stone-500 hover:text-stone-800">+ Agregar partida manual</button>
          </div>
          <p className="text-[11px] text-stone-500">Con facturas cargadas, usa <b>Desglosar por factura</b> (es el flujo normal: separa baterías y controles de cada sistema). <b>Auto‑asignar</b> es solo para captura sin factura.</p>
          {empateMsg && <p className="text-[11px] text-teal-700 font-medium">{empateMsg}</p>}
        </div>
      </Section>

      {gruposFactura.length > 0 && (
        <Section n="2b" t="Órdenes de compra (Books)" r={`${gruposFactura.length} factura${gruposFactura.length > 1 ? "s" : ""}`}>
          <div className="p-4 space-y-3">
            <div className="flex flex-wrap items-center gap-3 justify-between">
              <div className="text-[11px] text-stone-500">
                Pedimento <b className="font-mono text-stone-700">{ped.numero || "—"}</b> · {ped.fecha || "—"} · TC <b className="font-mono text-stone-700">{tc || "—"}</b> · {gruposFactura.length} factura{gruposFactura.length > 1 ? "s" : ""}
              </div>
              <button onClick={buscarOCs} disabled={buscandoOC} className="px-4 py-2 bg-teal-700 text-white text-xs font-semibold rounded-lg hover:bg-teal-800 disabled:opacity-40">{buscandoOC ? "Buscando…" : "🔎 Auto-buscar OC en Books"}</button>
            </div>
            {ocMsg && <p className="text-[11px] text-stone-600">{ocMsg}</p>}
            <div className="divide-y divide-stone-100 border border-stone-200 rounded-lg">
              {gruposFactura.map((g) => (
                <div key={g.factura} className="flex flex-wrap items-center justify-between gap-2 p-3">
                  <div className="text-xs">
                    <span className="font-mono font-semibold">{g.factura}</span>
                    <span className="ml-3 text-stone-500">{g.qty} pzas · ${mx0(g.fobUSD)} USD</span>
                  </div>
                  <div className="flex items-center gap-2">
                    <span className="text-[10px] uppercase tracking-widest text-stone-400">OC</span>
                    <input list="pendpos" value={g.oc} onChange={(e) => setOcGrupo(g.ids, e.target.value.toUpperCase())} placeholder="PO-…" className={inp + " font-mono max-w-[180px]"} />
                  </div>
                </div>
              ))}
              <datalist id="pendpos">{pendPOs.map((n) => <option key={n} value={n} />)}</datalist>
            </div>
            <p className="text-[10px] text-stone-400">El botón trae las OC de Renon <strong>pendientes por surtir</strong> y propone una por factura (estimada, por equipos/guía). <strong>Confírmala o cámbiala a mano</strong> — al escribir en el campo aparecen las OC pendientes para elegir. Se copia a todos los SKU de esa factura.</p>
          </div>
        </Section>
      )}

      {mixto && (
        <div className="bg-amber-50 border border-amber-300 rounded-lg px-4 py-3 text-xs text-amber-900">
          ⚠ Embarque mixto (categorías con IGI distinto). Captura el IGI <strong>manual por partida</strong> tal como viene en el cuadro de liquidación del pedimento — no lo prorratees por valor.
        </div>
      )}

      <Section n="3" t="Incrementables" r={`Capitaliza $${mx0(calc.lineas.reduce((a, b) => a + b.incr, 0))}`}>
        <div className="divide-y divide-stone-100">
          {incs.map((c) => (
            <div key={c.id} className="p-3 grid grid-cols-2 md:grid-cols-12 gap-2 items-end">
              <div className="md:col-span-3"><Lbl>Concepto</Lbl><input className={inp} value={c.concepto} onChange={(e) => upd(setIncs)(c.id, "concepto", e.target.value)} /></div>
              <div className="md:col-span-2"><Lbl>Proveedor</Lbl><input className={inp} value={c.proveedor} onChange={(e) => upd(setIncs)(c.id, "proveedor", e.target.value)} /></div>
              <div className="md:col-span-2"><Lbl>Importe</Lbl><div className="flex gap-1">
                <input type="number" step="0.01" disabled={c.metodo === "manual"} className={inp + " font-mono text-right disabled:bg-stone-100"} value={c.metodo === "manual" ? "" : c.monto} onChange={(e) => upd(setIncs)(c.id, "monto", e.target.value)} />
                <select className={inp + " w-14 font-mono"} value={c.moneda} onChange={(e) => upd(setIncs)(c.id, "moneda", e.target.value)}><option>MXN</option><option>USD</option></select>
              </div></div>
              <div className="md:col-span-2"><Lbl>Prorrateo</Lbl><select className={inp} value={c.metodo} onChange={(e) => upd(setIncs)(c.id, "metodo", e.target.value)}>{Object.entries(METODOS).map(([k, v]) => <option key={k} value={k}>{v}</option>)}</select></div>
              <div className="md:col-span-2"><Lbl>Documento</Lbl><select className={inp} value={c.estadoDoc} onChange={(e) => upd(setIncs)(c.id, "estadoDoc", e.target.value)}>{Object.entries(ESTADOS_DOC).map(([k, v]) => <option key={k} value={k}>{v}</option>)}</select></div>
              <div className="md:col-span-1">
                <Lbl>Costo</Lbl>
                <button onClick={() => upd(setIncs)(c.id, "capitaliza", !c.capitaliza)}
                  className={`w-full px-1 py-1.5 text-[11px] font-medium rounded border ${c.capitaliza ? "bg-teal-50 border-teal-400 text-teal-800" : "bg-stone-100 border-stone-300 text-stone-500"}`}>
                  {c.capitaliza ? "Sí" : "No"}
                </button>
              </div>
              {c.extra && (
                <div className="md:col-span-12 flex items-center gap-3 -mt-1">
                  <label className="text-[11px] text-teal-700 cursor-pointer">
                    📎 Adjuntar cotización/factura
                    <input type="file" className="hidden" onChange={(e) => { const f = e.target.files?.[0]; if (f) upd(setIncs)(c.id, "adjunto", f.name); }} />
                  </label>
                  {c.adjunto && <span className="text-[11px] font-mono text-stone-500">{c.adjunto}</span>}
                  <button onClick={() => setIncs((s) => s.filter((x) => x.id !== c.id))} className="text-[11px] text-stone-400 hover:text-red-600 ml-auto">quitar concepto</button>
                </div>
              )}
              {c.metodo === "manual" && calc.lineas.length > 0 && (
                <div className="md:col-span-12 pl-2 border-l-2 border-amber-400 mt-1">
                  <p className="text-[10px] uppercase tracking-widest text-stone-500 mb-1">IGI por partida (del cuadro de liquidación)</p>
                  <div className="flex flex-wrap gap-2">
                    {calc.lineas.map((l) => (
                      <div key={l.id} className="w-36"><span className="block text-[11px] font-mono text-stone-500 truncate">{l.sku}</span>
                        <input type="number" step="0.01" className={inp + " font-mono text-right"} value={c.manual?.[l.id] || ""} onChange={(e) => setIncs((s) => s.map((x) => (x.id === c.id ? { ...x, manual: { ...x.manual, [l.id]: e.target.value } } : x)))} />
                      </div>
                    ))}
                  </div>
                </div>
              )}
            </div>
          ))}
        </div>
        <div className="px-3 py-3 border-t border-stone-200 flex flex-wrap items-center gap-4">
          <button onClick={() => setIncs((s) => [...s, { id: uid(), concepto: "", proveedor: "", monto: "", moneda: "MXN", metodo: "valor", capitaliza: true, estadoDoc: "estimado", manual: {}, extra: true, adjunto: "" }])}
            className="text-xs font-medium text-teal-700">+ Agregar costo extra (maniobra, flete adicional, otro)</button>
          {calc.noCap > 0 && <span className="text-[11px] font-mono text-stone-500">Fuera del costo (IVA acreditable): ${mx0(calc.noCap)}</span>}
        </div>
      </Section>

      <Section n="3b" t="Adjuntos de la importación" r="Cotizaciones, facturas, packing list, etc.">
        <div className="p-4">
          <label className="inline-block px-3 py-2 bg-stone-900 text-white text-xs font-medium rounded cursor-pointer hover:bg-stone-800">
            + Adjuntar archivo
            <input type="file" className="hidden" onChange={(e) => { const f = e.target.files?.[0]; if (f) { setAdjuntos((a) => [...a, f.name]); e.target.value = ""; } }} />
          </label>
          {adjuntos.length > 0 && (
            <ul className="mt-3 space-y-1">
              {adjuntos.map((nombre, i) => (
                <li key={i} className="flex items-center justify-between text-xs font-mono text-stone-600 border-b border-stone-100 py-1">
                  <span>📎 {nombre}</span>
                  <button onClick={() => setAdjuntos((a) => a.filter((_, j) => j !== i))} className="text-stone-400 hover:text-red-600">quitar</button>
                </li>
              ))}
            </ul>
          )}
          <p className="mt-2 text-[11px] text-stone-400">Se guarda el nombre del archivo como referencia. El adjunto físico va en Zoho, ligado al bill del proveedor.</p>
        </div>
      </Section>

      <Section n="4" t="Costo unitario provisional">
        {calc.lineas.length === 0 ? <p className="p-6 text-sm text-stone-500">Captura partidas para ver el costo.</p> : (
          <div className="divide-y divide-stone-100">
            {calc.lineas.map((l) => {
              const vig = catalogo[l.sku]?.costoVigente;
              return (
                <div key={l.id} className="p-4 flex flex-wrap items-baseline justify-between gap-2">
                  <div><span className="font-mono text-sm font-semibold">{l.sku}</span><span className="ml-2 text-xs text-stone-500">{catalogo[l.sku]?.descripcion || l.desc}</span></div>
                  <div className="text-right font-mono text-xs text-stone-500">
                    {vig != null && <span className="mr-4">Zoho hoy ${mx(vig)}</span>}
                    <span className="text-sm font-semibold text-amber-700">landed ${mx(l.unit)}</span>
                  </div>
                </div>
              );
            })}
          </div>
        )}
        <div className="p-4 border-t border-stone-200 flex gap-2">
          <button onClick={guardar} disabled={!ped.numero.trim() || !tc || !calc.lineas.length || faltanOC} className="px-4 py-2 bg-stone-900 text-white text-sm font-medium rounded hover:bg-stone-800 disabled:opacity-40">Guardar como provisional</button>
          <button onClick={onCancel} className="px-4 py-2 border border-stone-300 text-sm rounded">Cancelar</button>
          {faltanOC && <span className="text-xs text-amber-700">⚠ Falta capturar la OC de cada factura (sección 2b) antes de guardar.</span>}
        </div>
      </Section>

      <Section n="5" t="Prorrateo detallado (vista equipo)" r="Costo landed por SKU · exportable">
        <ProrrateoDetalle pedNumero={ped.numero} lineas={calc.lineas} incs={incs} tc={tc} catalogo={catalogo} setPartidas={setPartidas} />
      </Section>

      <Section n="6" t="Resumen de la importación" r="Totales de lo gastado">
        {(() => {
          const fobUSD = calc.lineas.reduce((a, l) => a + (+l.fobUnit || 0) * l.cant, 0);
          const incsRes = incs.map((c) => ({ concepto: c.concepto, mxn: c.metodo === "manual" ? Object.values(c.manual || {}).reduce((a, b) => a + (+b || 0), 0) : (c.moneda === "USD" ? (+c.monto || 0) * tc : (+c.monto || 0)), cap: c.capitaliza })).filter((x) => x.mxn > 0);
          const capMXN = incsRes.filter((x) => x.cap).reduce((a, b) => a + b.mxn, 0);
          const noCapMXN = incsRes.filter((x) => !x.cap).reduce((a, b) => a + b.mxn, 0);
          const landed = calc.lineas.reduce((a, l) => a + l.total, 0);
          const kpi = (t, v) => (<div className="bg-stone-50 rounded-lg p-3"><p className="text-[10px] uppercase tracking-widest text-stone-400">{t}</p><p className="text-sm font-semibold font-mono mt-0.5">{v}</p></div>);
          return (
            <div className="p-4 space-y-4">
              <div className="grid grid-cols-2 md:grid-cols-4 gap-2">
                {kpi("Artículos (pzas)", mx0(calc.totC))}
                {kpi("Renglones / SKU", calc.lineas.length)}
                {kpi("Equipos FOB (USD)", "$" + mx0(fobUSD))}
                {kpi("Equipos FOB (MXN)", "$" + mx0(calc.totV))}
                {kpi("Incrementables (capitalizan)", "$" + mx0(capMXN))}
                {kpi("IVA acreditable", "$" + mx0(noCapMXN))}
                {kpi("Costo landed total (MXN)", "$" + mx0(landed))}
                {kpi("OC que amparan", ocsAmparan.length || "—")}
              </div>
              <div>
                <p className="text-[10px] uppercase tracking-widest text-stone-400 mb-1">Desglose de lo gastado (MXN)</p>
                <table className="w-full text-xs">
                  <tbody>
                    <tr className="border-b border-stone-100"><td className="py-1">Equipos (FOB)</td><td className="text-right font-mono">${mx0(calc.totV)}</td><td className="pl-3 text-stone-400">equipos</td></tr>
                    {incsRes.map((x) => (<tr key={x.concepto} className="border-b border-stone-100"><td className="py-1">{x.concepto}</td><td className="text-right font-mono">${mx0(x.mxn)}</td><td className="pl-3 text-stone-400">{x.cap ? "capitaliza" : "acreditable"}</td></tr>))}
                    <tr className="border-t-2 border-stone-200 font-semibold"><td className="py-1.5">Costo landed total (equipos + capitalizables)</td><td className="text-right font-mono">${mx0(landed)}</td><td className="pl-3 text-stone-400">MXN</td></tr>
                    <tr className="font-semibold"><td className="py-1">Desembolso total (landed + IVA)</td><td className="text-right font-mono">${mx0(landed + noCapMXN)}</td><td className="pl-3 text-stone-400">MXN</td></tr>
                  </tbody>
                </table>
                {ocsAmparan.length > 0 && <p className="mt-2 text-[11px] text-stone-500">OC que amparan: <span className="font-mono">{ocsAmparan.join(", ")}</span></p>}
              </div>
            </div>
          );
        })()}
      </Section>
    </div>
  );
}

/* ---------- Detalle / cierre de pedimento ---------- */
function DetallePedimento({ ped, catalogo, saveCatalogo, pedimentos, savePedimentos, setAviso, onBack }) {
  const st = estadoPedimento(ped);
  const calc = useMemo(() => prorratear(ped.partidas, ped.incrementables, ped.tc), [ped]);

  const setEstadoDoc = (incId, val) => {
    const nuevo = { ...ped, incrementables: ped.incrementables.map((i) => (i.id === incId ? { ...i, estadoDoc: val } : i)) };
    savePedimentos(pedimentos.map((p) => (p.id === ped.id ? nuevo : p)));
  };
  const setMonto = (incId, val) => {
    const nuevo = { ...ped, incrementables: ped.incrementables.map((i) => (i.id === incId ? { ...i, monto: +val || 0 } : i)) };
    savePedimentos(pedimentos.map((p) => (p.id === ped.id ? nuevo : p)));
  };

  const cerrar = () => {
    const c = { ...catalogo };
    const alertas = [];
    calc.lineas.forEach((l) => {
      const sku = l.sku.trim().toUpperCase();
      const a = c[sku] || { descripcion: l.desc, categoria: l.categoria, existencia: 0, costoVigente: l.unit, historia: [] };
      const prov = ped.provisional?.find((x) => x.sku === l.sku)?.unit;
      if (prov != null && Math.abs(l.unit - prov) / (prov || 1) > UMBRAL) alertas.push(`${sku}: real difiere ${((l.unit - prov) / prov * 100).toFixed(1)}% del provisional`);
      const exist = a.existencia || 0;
      const nuevoQty = exist + l.cant;
      const nuevoProm = nuevoQty ? (exist * a.costoVigente + l.total) / nuevoQty : l.unit;
      c[sku] = {
        ...a,
        existencia: nuevoQty,
        promedioPendiente: nuevoProm,
        historia: [...(a.historia || []), { fecha: ped.fecha, pedimento: ped.numero, qty: l.cant, unitCost: l.unit, avgResult: nuevoProm, estado: "final" }],
      };
    });
    saveCatalogo(c);
    savePedimentos(pedimentos.map((p) => (p.id === ped.id ? { ...ped, cerrado: true } : p)));
    setAviso({ t: alertas.length ? "err" : "ok", m: alertas.length ? `Cerrado con avisos: ${alertas.join(" · ")}. Revisa antes de enviar a Zoho.` : `Pedimento ${ped.numero} cerrado. Nuevos promedios listos en Artículos para enviar a Zoho.` });
    onBack();
  };

  const inp = "px-2 py-1 text-sm bg-white border border-stone-300 rounded focus:outline-none focus:ring-2 focus:ring-teal-600";

  return (
    <div className="space-y-4">
      <div className="flex items-center justify-between">
        <div className="flex items-center gap-3"><h2 className="text-sm font-semibold font-mono">{ped.numero}</h2><EstadoBadge estado={st} /></div>
        <button onClick={onBack} className="text-xs text-stone-500 hover:text-stone-800">← Volver</button>
      </div>

      <Section n="·" t="Facturas de incrementables">
        <p className="px-4 pt-3 text-xs text-stone-500">Conforme llegan las facturas reales, cambia cada renglón de Estimado a Factura final. El pedimento se cierra cuando todo está en factura final.</p>
        <div className="divide-y divide-stone-100 mt-2">
          {ped.incrementables.filter((i) => i.capitaliza).map((i) => (
            <div key={i.id} className="px-4 py-2 flex flex-wrap items-center justify-between gap-2">
              <div><span className="text-sm">{i.concepto}</span><span className="ml-2 text-[11px] text-stone-400">{i.proveedor}</span></div>
              <div className="flex items-center gap-2">
                {i.metodo !== "manual" && <input type="number" disabled={ped.cerrado} value={i.monto || ""} onChange={(e) => setMonto(i.id, e.target.value)} className={inp + " w-28 font-mono text-right"} />}
                <span className="text-[10px] font-mono text-stone-400 w-8">{i.moneda}</span>
                <select disabled={ped.cerrado} value={i.estadoDoc} onChange={(e) => setEstadoDoc(i.id, e.target.value)} className={inp + ` ${i.estadoDoc === "final" ? "text-teal-700" : "text-amber-700"}`}>
                  {Object.entries(ESTADOS_DOC).map(([k, v]) => <option key={k} value={k}>{v}</option>)}
                </select>
              </div>
            </div>
          ))}
        </div>
      </Section>

      <Section n="·" t="Costo landed actual">
        <div className="divide-y divide-stone-100">
          {calc.lineas.map((l) => {
            const prov = ped.provisional?.find((x) => x.sku === l.sku)?.unit;
            const d = prov != null ? (l.unit - prov) / prov : 0;
            return (
              <div key={l.id} className="px-4 py-2 flex flex-wrap items-baseline justify-between gap-2 text-sm">
                <span><span className="font-mono font-semibold">{l.sku}</span><span className="ml-2 text-xs text-stone-500">{l.desc}</span></span>
                <span className="font-mono text-xs text-stone-500">
                  {prov != null && <span className="mr-3">prov ${mx(prov)}</span>}
                  <span className="text-sm font-semibold text-amber-700">${mx(l.unit)}</span>
                  {prov != null && Math.abs(d) > 0.0001 && <span className={`ml-2 ${Math.abs(d) > UMBRAL ? "text-red-600" : "text-stone-400"}`}>{d > 0 ? "+" : ""}{(d * 100).toFixed(1)}%</span>}
                </span>
              </div>
            );
          })}
        </div>
        {!ped.cerrado && (
          <div className="p-4 border-t border-stone-200">
            {st === "listo" ? (
              <button onClick={cerrar} className="px-4 py-2 bg-teal-700 text-white text-sm font-medium rounded hover:bg-teal-800">Cerrar y calcular nuevo promedio</button>
            ) : (
              <p className="text-xs text-stone-500">Faltan facturas finales. Marca todos los incrementables como <strong>Factura final</strong> para poder cerrar.</p>
            )}
          </div>
        )}
        {ped.cerrado && <div className="p-4 border-t border-stone-200 text-xs text-teal-700">Pedimento cerrado. Los nuevos promedios están en la pestaña Artículos, listos para enviar a Zoho.</div>}
      </Section>
    </div>
  );
}

/* ===================== TAB 3 · FLETES ===================== */
function Fletes({ fletes, saveFletes }) {
  const upd = (id, k, v) => saveFletes(fletes.map((f) => (f.id === id ? { ...f, [k]: v } : f)));
  const inp = "px-2 py-1.5 text-sm bg-white border border-stone-300 rounded focus:outline-none focus:ring-2 focus:ring-teal-600";
  return (
    <div className="space-y-4">
      <div><h2 className="text-sm font-semibold">Catálogo de fletes</h2><p className="text-xs text-stone-500">Tarifas fijas editables. Cada nueva importación las toma como estimado inicial; las importaciones ya cerradas no cambian.</p></div>
      <div className="bg-white border border-stone-200 rounded-lg divide-y divide-stone-100">
        {fletes.map((f) => (
          <div key={f.id} className="p-3 grid grid-cols-2 md:grid-cols-12 gap-2 items-end">
            <div className="md:col-span-4"><Lbl>Tramo</Lbl><input className={inp + " w-full"} value={f.tramo} onChange={(e) => upd(f.id, "tramo", e.target.value)} /></div>
            <div className="md:col-span-3"><Lbl>Proveedor</Lbl><input className={inp + " w-full"} value={f.proveedor} onChange={(e) => upd(f.id, "proveedor", e.target.value)} /></div>
            <div className="md:col-span-2"><Lbl>Tarifa fija</Lbl><input type="number" step="0.01" className={inp + " w-full font-mono text-right"} value={f.tarifa} onChange={(e) => upd(f.id, "tarifa", +e.target.value || 0)} /></div>
            <div className="md:col-span-1"><Lbl>Mon.</Lbl><select className={inp + " w-full font-mono"} value={f.moneda} onChange={(e) => upd(f.id, "moneda", e.target.value)}><option>MXN</option><option>USD</option></select></div>
            <div className="md:col-span-2"><Lbl>En pedimento</Lbl><button onClick={() => upd(f.id, "incrementable", !f.incrementable)} className={`w-full px-2 py-1.5 text-xs font-medium rounded border ${f.incrementable ? "bg-teal-50 border-teal-400 text-teal-800" : "bg-stone-100 border-stone-300 text-stone-500"}`}>{f.incrementable ? "Sí declara" : "No declara"}</button></div>
          </div>
        ))}
      </div>
      <button onClick={() => saveFletes([...fletes, { id: uid(), tramo: "", proveedor: "", tarifa: 0, moneda: "MXN", incrementable: false }])} className="text-xs font-medium text-teal-700">+ Agregar tramo</button>
    </div>
  );
}

/* ===================== MÓDULO · INVENTARIO (almacén) ===================== */
function Inventario({ catalogo, saveCatalogo, setAviso }) {
  const [busca, setBusca] = useState("");
  const [modo, setModo] = useState("lista");
  const q = busca.trim().toLowerCase();
  const rows = Object.entries(catalogo)
    .filter(([sku, a]) => !q || sku.toLowerCase().includes(q) || (a.descripcion || "").toLowerCase().includes(q))
    .sort((a, b) => (a[1].existencia || 0) - (b[1].existencia || 0));
  const totalPzas = rows.reduce((s, [, a]) => s + (a.existencia || 0), 0);
  const bajo = rows.filter(([, a]) => (a.existencia || 0) <= 5).length;

  if (modo === "recepcion")
    return <RecepcionCamara catalogo={catalogo} saveCatalogo={saveCatalogo} setAviso={setAviso} onSalir={() => setModo("lista")} />;

  return (
    <div className="space-y-4">
      <div className="flex flex-wrap items-start justify-between gap-2">
        <div>
          <h2 className="text-sm font-semibold">Inventario</h2>
          <p className="text-xs text-stone-500">Existencias por artículo. Vista para almacén.</p>
        </div>
        <button onClick={() => setModo("recepcion")} className="px-3 py-2 bg-teal-700 text-white text-xs font-medium rounded hover:bg-teal-800">📷 Recepción por cámara</button>
      </div>
      <div className="grid grid-cols-3 gap-2">
        <Kpi t="Artículos" v={rows.length} />
        <Kpi t="Piezas totales" v={totalPzas} />
        <Kpi t="Stock bajo (≤5)" v={bajo} alerta={bajo > 0} />
      </div>
      <input value={busca} onChange={(e) => setBusca(e.target.value)} placeholder="Buscar SKU o artículo…"
        className="w-full px-3 py-2 text-sm bg-white border border-stone-300 rounded focus:outline-none focus:ring-2 focus:ring-teal-600" />
      {rows.length > 200 && <p className="text-[11px] font-mono text-stone-500">Mostrando 200 de {rows.length} — usa el buscador para filtrar.</p>}
      <div className="bg-white border border-stone-200 rounded-lg overflow-x-auto">
        <table className="w-full min-w-[520px] text-sm">
          <thead className="bg-stone-50 border-b border-stone-200">
            <tr className="text-[10px] uppercase tracking-widest text-stone-500">
              <th className="text-left px-3 py-2">SKU</th>
              <th className="text-left px-3 py-2">Artículo</th>
              <th className="text-right px-3 py-2">Existencia</th>
              <th className="text-left px-3 py-2 pl-4">Estado</th>
            </tr>
          </thead>
          <tbody>
            {rows.slice(0, 200).map(([sku, a]) => {
              const ex = a.existencia || 0;
              const estado = ex === 0 ? ["Agotado", "bg-red-100 text-red-700"] : ex <= 5 ? ["Stock bajo", "bg-amber-100 text-amber-800"] : ["OK", "bg-teal-100 text-teal-800"];
              return (
                <tr key={sku} className="border-b border-stone-100">
                  <td className="px-3 py-2 font-mono text-xs font-semibold">{sku}</td>
                  <td className="px-3 py-2 text-stone-600 text-xs">{a.descripcion}</td>
                  <td className="px-3 py-2 text-right font-mono">{ex}</td>
                  <td className="px-3 py-2 pl-4"><span className={`px-2 py-0.5 text-[10px] rounded font-medium ${estado[1]}`}>{estado[0]}</span></td>
                </tr>
              );
            })}
          </tbody>
        </table>
      </div>
    </div>
  );
}

/* Sonido sintético tipo escáner */
function clank() {
  try {
    const AC = window.AudioContext || window.webkitAudioContext;
    if (!AC) return;
    const ac = new AC();
    const o = ac.createOscillator(), g = ac.createGain();
    o.type = "square"; o.frequency.setValueAtTime(220, ac.currentTime); o.frequency.exponentialRampToValueAtTime(90, ac.currentTime + 0.1);
    g.gain.setValueAtTime(0.25, ac.currentTime); g.gain.exponentialRampToValueAtTime(0.001, ac.currentTime + 0.13);
    o.connect(g); g.connect(ac.destination); o.start(); o.stop(ac.currentTime + 0.13);
  } catch { /* silencio si no hay audio */ }
}

function RecepcionCamara({ catalogo, saveCatalogo, setAviso, onSalir }) {
  const videoRef = useRef(null);
  const streamRef = useRef(null);
  const [camError, setCamError] = useState(null);
  const [estado, setEstado] = useState("listo"); // listo | leyendo | confirmar | error
  const [flash, setFlash] = useState(null); // "verde" | "rojo"
  const [detectado, setDetectado] = useState(null); // {sku, descripcion, cantidad, serie}
  const [capturas, setCapturas] = useState([]); // acumulado

  useEffect(() => {
    (async () => {
      try {
        const s = await navigator.mediaDevices.getUserMedia({ video: { facingMode: "environment" } });
        streamRef.current = s;
        if (videoRef.current) { videoRef.current.srcObject = s; await videoRef.current.play().catch(() => {}); }
      } catch {
        setCamError("No se pudo abrir la cámara en este entorno. Usa “Subir foto”.");
      }
    })();
    return () => { if (streamRef.current) streamRef.current.getTracks().forEach((t) => t.stop()); };
  }, []);

  const skuList = Object.entries(catalogo).map(([sku, a]) => `${sku}: ${a.descripcion}`).join("\n");
  const PROMPT = `Eres un asistente de almacén. La imagen es la etiqueta o caja de un producto de energía solar (batería, inversor, panel, control) recién llegado.
Catálogo de SKU disponibles:
${skuList}

Lee la etiqueta y responde ÚNICAMENTE JSON compacto, sin markdown:
{"sku":"","modelo":"","cantidad":1,"serie":""}
- sku: el SKU del catálogo que mejor corresponda al modelo leído; si ninguno corresponde, "".
- modelo: el texto del modelo/descripción que leíste.
- cantidad: número de piezas si la etiqueta lo indica; si no, 1.
- serie: número de serie si aparece; si no, "".
Si la imagen está borrosa o no es una etiqueta de producto, responde {"error":"ilegible"}.`;

  const leerImagen = async (b64) => {
    setEstado("leyendo"); setDetectado(null);
    try {
      const data = await window.aiExtract({ model: "claude-sonnet-5", max_tokens: 1500, messages: [{ role: "user", content: [{ type: "image", source: { type: "base64", media_type: "image/jpeg", data: b64 } }, { type: "text", text: PROMPT }] }] });
      const txt = (data.content || []).filter((i) => i.type === "text").map((i) => i.text).join("").replace(/```json|```/g, "").trim();
      const p = extraerJSON(txt);
      if (p.error || (!p.sku && !p.modelo)) { setFlash("rojo"); setEstado("error"); setTimeout(() => setFlash(null), 600); return; }
      const desc = catalogo[p.sku]?.descripcion || p.modelo || "Modelo no reconocido";
      setDetectado({ sku: p.sku || "", descripcion: desc, cantidad: +p.cantidad || 1, serie: p.serie || "" });
      setEstado("confirmar");
    } catch {
      setFlash("rojo"); setEstado("error"); setTimeout(() => setFlash(null), 600);
    }
  };

  const disparar = () => {
    clank();
    const v = videoRef.current;
    if (!v || !v.videoWidth) { setCamError("Cámara no lista. Usa “Subir foto”."); return; }
    const cv = document.createElement("canvas");
    cv.width = v.videoWidth; cv.height = v.videoHeight;
    cv.getContext("2d").drawImage(v, 0, 0);
    leerImagen(cv.toDataURL("image/jpeg", 0.7).split(",")[1]);
  };

  const subirFoto = async (file) => {
    if (!file) return;
    clank();
    const b64 = await new Promise((res) => { const r = new FileReader(); r.onload = () => res(r.result.split(",")[1]); r.readAsDataURL(file); });
    leerImagen(b64);
  };

  const agregarItem = (item) => {
    setCapturas((cs) => {
      const key = item.sku || item.descripcion;
      const idx = cs.findIndex((c) => (c.sku || c.descripcion) === key);
      const series = item.serie ? [item.serie] : (item.series || []);
      if (idx >= 0) {
        const cp = [...cs];
        cp[idx] = { ...cp[idx], cantidad: cp[idx].cantidad + (item.cantidad || 1), series: [...cp[idx].series, ...series] };
        return cp;
      }
      return [...cs, { sku: item.sku || "", descripcion: item.descripcion, cantidad: item.cantidad || 1, series }];
    });
  };

  const agregar = () => {
    clank(); setFlash("verde"); setTimeout(() => setFlash(null), 600);
    agregarItem(detectado);
    setDetectado(null); setEstado("listo");
  };

  const [manualAbierto, setManualAbierto] = useState(false);
  const [man, setMan] = useState({ sku: "", cantidad: 1, serie: "" });
  const agregarManual = () => {
    if (!man.sku) return;
    agregarItem({ sku: man.sku, descripcion: catalogo[man.sku]?.descripcion || man.sku, cantidad: +man.cantidad || 1, serie: man.serie });
    clank(); setFlash("verde"); setTimeout(() => setFlash(null), 400);
    setMan({ sku: "", cantidad: 1, serie: "" }); setManualAbierto(false);
  };

  const [leyendoDoc, setLeyendoDoc] = useState(false);
  const subirDoc = async (file) => {
    if (!file) return;
    setLeyendoDoc(true);
    try {
      const b64 = await new Promise((res) => { const r = new FileReader(); r.onload = () => res(r.result.split(",")[1]); r.readAsDataURL(file); });
      const prompt = `Es una orden de compra o pedimento de importación. Extrae los renglones de mercancía y responde SOLO JSON compacto: {"items":[{"sku":"","modelo":"","cantidad":0}]}. Empata cada renglón con el catálogo:\n${skuList}\nUsa el SKU del catálogo que corresponda; si ninguno, "".`;
      const data = await window.aiExtract({ model: "claude-sonnet-5", max_tokens: 3000, messages: [{ role: "user", content: [{ type: "document", source: { type: "base64", media_type: "application/pdf", data: b64 } }, { type: "text", text: prompt }] }] });
      const txt = (data.content || []).filter((i) => i.type === "text").map((i) => i.text).join("").replace(/```json|```/g, "").trim();
      const p = extraerJSON(txt);
      (p.items || []).forEach((it) => agregarItem({ sku: it.sku || "", descripcion: catalogo[it.sku]?.descripcion || it.modelo || "Modelo", cantidad: +it.cantidad || 1 }));
      clank(); setFlash("verde"); setTimeout(() => setFlash(null), 500);
      setAviso({ t: "ok", m: `Documento leído: ${(p.items || []).length} renglones agregados a la lista.` });
    } catch {
      setAviso({ t: "err", m: "No se pudo leer el documento. Intenta con mejor calidad o captura manual." });
    }
    setLeyendoDoc(false);
  };

  const confirmarEntrada = () => {
    const c = { ...catalogo };
    capturas.forEach((cap) => {
      if (!cap.sku) return; // sin SKU reconocido no toca inventario
      const a = c[cap.sku] || { descripcion: cap.descripcion, categoria: "Otro", existencia: 0, costoVigente: 0 };
      c[cap.sku] = { ...a, existencia: (a.existencia || 0) + cap.cantidad, series: [...(a.series || []), ...cap.series] };
    });
    saveCatalogo(c);
    setAviso({ t: "ok", m: `Entrada registrada: ${capturas.reduce((s, x) => s + x.cantidad, 0)} pzas en ${capturas.length} modelos.` });
    setCapturas([]); onSalir();
  };

  const totalPzas = capturas.reduce((s, c) => s + c.cantidad, 0);
  const borde = flash === "verde" ? "ring-4 ring-teal-400" : flash === "rojo" ? "ring-4 ring-red-400" : estado === "leyendo" ? "ring-4 ring-amber-400" : "ring-1 ring-stone-300";

  return (
    <div className="space-y-4">
      <div className="flex items-center justify-between">
        <h2 className="text-sm font-semibold">Recepción por cámara</h2>
        <button onClick={onSalir} className="text-xs text-stone-500 hover:text-stone-800">← Volver a inventario</button>
      </div>

      <div className={`relative rounded-lg overflow-hidden bg-black aspect-[4/3] ${borde}`}>
        <video ref={videoRef} playsInline muted className="w-full h-full object-cover" />
        {camError && <div className="absolute inset-0 flex items-center justify-center bg-stone-800 text-stone-300 text-xs text-center p-4">{camError}</div>}
        {estado === "leyendo" && <div className="absolute inset-0 flex items-center justify-center bg-black/40"><p className="text-amber-300 text-sm font-mono">leyendo etiqueta…</p></div>}
        {flash === "verde" && <div className="absolute inset-0 flex items-center justify-center bg-teal-500/30"><p className="text-white text-4xl">✓</p></div>}
        {flash === "rojo" && <div className="absolute inset-0 flex items-center justify-center bg-red-500/30"><p className="text-white text-sm">✗ repite la foto</p></div>}

        {/* Recuadro de confirmación sobre la foto */}
        {estado === "confirmar" && detectado && (
          <div className="absolute inset-x-3 bottom-3 bg-white rounded-lg shadow-xl p-3">
            <p className="text-[10px] uppercase tracking-widest text-stone-500">Detectado</p>
            <p className="text-sm font-semibold">{detectado.descripcion}</p>
            {detectado.sku ? <p className="text-[11px] font-mono text-teal-700">{detectado.sku}</p> : <p className="text-[11px] text-amber-700">⚠ SKU no reconocido — elige o corrige</p>}
            {!detectado.sku && (
              <select className="mt-1 w-full px-2 py-1 text-xs border border-stone-300 rounded" value="" onChange={(e) => setDetectado({ ...detectado, sku: e.target.value, descripcion: catalogo[e.target.value]?.descripcion || detectado.descripcion })}>
                <option value="">— Empatar con SKU —</option>
                {Object.entries(catalogo).map(([sku, a]) => <option key={sku} value={sku}>{sku} · {a.descripcion}</option>)}
              </select>
            )}
            <div className="mt-2 flex items-center gap-2">
              <div className="flex items-center gap-1">
                <button onClick={() => setDetectado((d) => ({ ...d, cantidad: Math.max(1, d.cantidad - 1) }))} className="w-8 h-8 rounded border border-stone-300 text-lg">−</button>
                <input type="number" value={detectado.cantidad} onChange={(e) => setDetectado((d) => ({ ...d, cantidad: +e.target.value || 1 }))} className="w-14 text-center px-1 py-1.5 text-sm border border-stone-300 rounded font-mono" />
                <button onClick={() => setDetectado((d) => ({ ...d, cantidad: d.cantidad + 1 }))} className="w-8 h-8 rounded border border-stone-300 text-lg">+</button>
              </div>
              <span className="text-xs text-stone-500">pzas</span>
              {detectado.serie && <span className="text-[11px] font-mono text-stone-500 ml-auto truncate">Serie: {detectado.serie}</span>}
            </div>
            <div className="mt-2 flex gap-2">
              <button onClick={() => { setDetectado(null); setEstado("listo"); }} className="flex-1 py-2 text-xs rounded border border-stone-300">Repetir</button>
              <button onClick={agregar} className="flex-1 py-2 text-xs rounded bg-teal-700 text-white font-medium">Aceptar y seguir ✓</button>
            </div>
          </div>
        )}
      </div>

      {/* Controles de captura */}
      {estado !== "confirmar" && (
        <>
          <div className="flex items-center gap-2">
            <button onClick={disparar} disabled={estado === "leyendo"} className="flex-1 py-3 bg-stone-900 text-white text-sm font-semibold rounded-lg disabled:opacity-40">● Capturar</button>
            <label className="py-3 px-4 border border-stone-300 rounded-lg text-sm cursor-pointer">Subir foto
              <input type="file" accept="image/*" capture="environment" className="hidden" onChange={(e) => subirFoto(e.target.files?.[0])} />
            </label>
          </div>
          <div className="flex items-center gap-2">
            <button onClick={() => setManualAbierto((v) => !v)} className="flex-1 py-2 border border-stone-300 rounded-lg text-xs font-medium text-stone-700">✏️ Ingresar manual</button>
            <label className="flex-1 py-2 border border-stone-300 rounded-lg text-xs font-medium text-stone-700 text-center cursor-pointer">
              {leyendoDoc ? "leyendo documento…" : "📄 Subir OC / Pedimento"}
              <input type="file" accept="application/pdf" className="hidden" disabled={leyendoDoc} onChange={(e) => subirDoc(e.target.files?.[0])} />
            </label>
          </div>
          {manualAbierto && (
            <div className="bg-white border border-stone-200 rounded-lg p-3 space-y-2">
              <p className="text-[10px] uppercase tracking-widest text-stone-500">Entrada manual</p>
              <select className="w-full px-2 py-1.5 text-sm border border-stone-300 rounded" value={man.sku} onChange={(e) => setMan({ ...man, sku: e.target.value })}>
                <option value="">— Elegir artículo —</option>
                {Object.entries(catalogo).map(([sku, a]) => <option key={sku} value={sku}>{sku} · {a.descripcion}</option>)}
              </select>
              <div className="flex items-center gap-2">
                <div className="flex items-center gap-1">
                  <button onClick={() => setMan((m) => ({ ...m, cantidad: Math.max(1, m.cantidad - 1) }))} className="w-8 h-8 rounded border border-stone-300 text-lg">−</button>
                  <input type="number" value={man.cantidad} onChange={(e) => setMan({ ...man, cantidad: +e.target.value || 1 })} className="w-14 text-center px-1 py-1.5 text-sm border border-stone-300 rounded font-mono" />
                  <button onClick={() => setMan((m) => ({ ...m, cantidad: m.cantidad + 1 }))} className="w-8 h-8 rounded border border-stone-300 text-lg">+</button>
                </div>
                <input value={man.serie} onChange={(e) => setMan({ ...man, serie: e.target.value })} placeholder="Serie (opcional)" className="flex-1 px-2 py-1.5 text-sm border border-stone-300 rounded font-mono" />
              </div>
              <button onClick={agregarManual} disabled={!man.sku} className="w-full py-2 text-xs rounded bg-teal-700 text-white font-medium disabled:opacity-40">Agregar a la lista</button>
            </div>
          )}
        </>
      )}

      {/* Lista acumulada */}
      <div className="bg-white border border-stone-200 rounded-lg">
        <div className="px-4 py-2.5 border-b border-stone-200 flex items-baseline justify-between">
          <h3 className="text-sm font-semibold">Escaneado</h3>
          <span className="text-[11px] font-mono text-stone-500">{totalPzas} pzas · {capturas.length} modelos</span>
        </div>
        {capturas.length === 0 ? (
          <p className="p-6 text-sm text-stone-500 text-center">Apunta a la etiqueta y captura. Cada modelo se va acumulando aquí.</p>
        ) : (
          <div className="divide-y divide-stone-50">
            {capturas.map((c, i) => (
              <div key={i} className="px-4 py-2 flex items-center justify-between gap-2">
                <div className="min-w-0">
                  <p className="text-sm truncate">{c.descripcion}</p>
                  <p className="text-[11px] font-mono text-stone-400">{c.sku || "sin SKU"}{c.series.length ? ` · ${c.series.length} serie(s)` : ""}</p>
                </div>
                <div className="flex items-center gap-2">
                  <span className="font-mono text-sm font-semibold">{c.cantidad}</span>
                  <button onClick={() => setCapturas((cs) => cs.filter((_, j) => j !== i))} className="text-stone-400 hover:text-red-600 text-sm">×</button>
                </div>
              </div>
            ))}
          </div>
        )}
        {capturas.length > 0 && (
          <div className="p-3 border-t border-stone-200">
            <button onClick={confirmarEntrada} className="w-full py-2.5 bg-teal-700 text-white text-sm font-semibold rounded-lg">Confirmar entrada al inventario</button>
          </div>
        )}
      </div>
      <p className="text-[11px] text-stone-400">La cámara y la lectura funcionan en el navegador; el alta se guarda en la app y se empujará a Zoho Inventory al conectar la escritura. Los modelos sin SKU no tocan inventario hasta que los empates.</p>
    </div>
  );
}

function Kpi({ t, v, alerta }) {
  return (
    <div className={`rounded-lg border p-3 ${alerta ? "bg-amber-50 border-amber-300" : "bg-white border-stone-200"}`}>
      <p className="text-[10px] uppercase tracking-widest text-stone-500">{t}</p>
      <p className={`text-xl font-semibold font-mono ${alerta ? "text-amber-700" : "text-stone-900"}`}>{v}</p>
    </div>
  );
}

/* ===================== MÓDULO · ROADMAP ===================== */
function Mas(props) {
  return (
    <div className="space-y-5">
      <Respaldo {...props} />
      <GuiaSeries />
      <Roadmap />
    </div>
  );
}

function Respaldo({ catalogo, fletes, pedimentos, cuentas, operaciones, tcFix, saveCatalogo, saveFletes, savePedimentos, saveCuentas, saveOperaciones, saveTcFix, setAviso }) {
  const exportar = () => {
    const data = { _app: "AdminAppISO", _version: 1, _fecha: new Date().toISOString(), catalogo, fletes, pedimentos, cuentas, operaciones, tcFix };
    const a = document.createElement("a");
    a.href = URL.createObjectURL(new Blob([JSON.stringify(data)], { type: "application/json" }));
    a.download = `AdminAppISO-respaldo-${hoy()}.json`;
    a.click();
    setAviso({ t: "ok", m: "Respaldo descargado. Guárdalo en un lugar seguro." });
  };
  const importar = async (file) => {
    if (!file) return;
    try {
      const txt = await file.text();
      const d = extraerJSON(txt);
      if (d.catalogo) saveCatalogo(d.catalogo);
      if (d.fletes) saveFletes(d.fletes);
      if (d.pedimentos) savePedimentos(d.pedimentos);
      if (d.cuentas) saveCuentas(d.cuentas);
      if (d.operaciones) saveOperaciones(d.operaciones);
      if (d.tcFix != null) saveTcFix(d.tcFix);
      setAviso({ t: "ok", m: "Respaldo restaurado. Todos los datos se cargaron." });
    } catch {
      setAviso({ t: "err", m: "Archivo de respaldo inválido." });
    }
  };
  return (
    <div className="bg-white border border-stone-200 rounded-lg p-4">
      <h3 className="text-sm font-semibold">Respaldo de datos</h3>
      <p className="text-xs text-stone-500 mt-1">La app guarda todo en este dispositivo. Exporta un respaldo con frecuencia y para pasar los datos a otro equipo. Importar reemplaza los datos actuales.</p>
      <div className="mt-3 flex flex-wrap gap-2">
        <button onClick={exportar} className="px-4 py-2 bg-stone-900 text-white text-xs font-medium rounded hover:bg-stone-800">⬇ Exportar respaldo</button>
        <label className="px-4 py-2 border border-stone-300 text-xs font-medium rounded cursor-pointer">⬆ Importar respaldo
          <input type="file" accept="application/json" className="hidden" onChange={(e) => importar(e.target.files?.[0])} />
        </label>
      </div>
      <p className="mt-2 text-[11px] font-mono text-stone-400">{Object.keys(catalogo).length} artículos · {pedimentos.length} pedimentos · {operaciones.length} operaciones · {cuentas.length} cuentas</p>
    </div>
  );
}

