/* ===================== MÓDULO · TESORERÍA / OPERACIÓN DIARIA ===================== */
const enUSD = (monto, moneda, tc) => (moneda === "USD" ? monto : (tc ? monto / tc : 0));
const lunesDe = (fechaStr) => {
  const d = new Date(fechaStr + "T00:00:00");
  const day = (d.getDay() + 6) % 7; // 0 = lunes
  d.setDate(d.getDate() - day);
  return d.toISOString().slice(0, 10);
};

function Tesoreria({ cuentas, saveCuentas, operaciones, saveOperaciones, tcFix, saveTcFix, pedimentos, setAviso }) {
  const [modo, setModo] = useState("resumen"); // resumen | nueva | movimientos
  const [editando, setEditando] = useState(null);

  const cta = (id) => cuentas.find((c) => c.id === id);

  // Saldo actual por cuenta = semilla + neto de operaciones confirmadas
  const saldos = useMemo(() => {
    const m = {};
    cuentas.forEach((c) => (m[c.id] = c.saldo || 0));
    operaciones.filter((o) => o.estatus === "confirmado").forEach((o) => {
      const mo = +o.monto || 0;
      if (o.tipo === "ingreso") m[o.cuentaId] = (m[o.cuentaId] || 0) + mo;
      else if (o.tipo === "egreso") m[o.cuentaId] = (m[o.cuentaId] || 0) - mo;
      else if (o.tipo === "traspaso") { m[o.cuentaId] = (m[o.cuentaId] || 0) - mo; m[o.cuentaDestinoId] = (m[o.cuentaDestinoId] || 0) + mo; }
      else if (o.tipo === "cambio") { m[o.cuentaId] = (m[o.cuentaId] || 0) - mo; m[o.cuentaDestinoId] = (m[o.cuentaDestinoId] || 0) + (+o.montoDestino || 0); }
    });
    return m;
  }, [cuentas, operaciones]);

  const consolidadoUSD = cuentas.reduce((s, c) => s + enUSD(saldos[c.id] || 0, c.moneda, tcFix), 0);

  if (modo === "nueva")
    return <NuevaOperacion {...{ cuentas, tcFix, onCancel: () => setModo("resumen"), onSave: (op) => { saveOperaciones([op, ...operaciones]); setModo("movimientos"); setAviso({ t: "ok", m: `Operación registrada (${TIPOS_OP[op.tipo]}).` }); } }} />;

  if (editando)
    return <NuevaOperacion {...{ cuentas, tcFix, inicial: editando, onCancel: () => setEditando(null), onSave: (op) => { saveOperaciones(operaciones.map((o) => (o.id === op.id ? op : o))); setEditando(null); setModo("movimientos"); setAviso({ t: "ok", m: "Movimiento actualizado." }); } }} />;

  return (
    <div className="space-y-4">
      <div className="flex flex-wrap items-center justify-between gap-2">
        <div>
          <h2 className="text-sm font-semibold">Tesorería</h2>
          <p className="text-xs text-stone-500">Operación diaria y flujo. Cada cuenta en su moneda; el total consolida a USD al TC fix.</p>
        </div>
        <div className="flex gap-2">
          <button onClick={() => setModo("resumen")} className={`px-3 py-2 text-xs font-medium rounded ${modo === "resumen" ? "bg-stone-900 text-white" : "border border-stone-300 text-stone-600"}`}>Resumen</button>
          <button onClick={() => setModo("flujo")} className={`px-3 py-2 text-xs font-medium rounded ${modo === "flujo" ? "bg-stone-900 text-white" : "border border-stone-300 text-stone-600"}`}>Flujo semanal</button>
          <button onClick={() => setModo("movimientos")} className={`px-3 py-2 text-xs font-medium rounded ${modo === "movimientos" ? "bg-stone-900 text-white" : "border border-stone-300 text-stone-600"}`}>Movimientos</button>
          <button onClick={() => setModo("nueva")} className="px-3 py-2 bg-teal-700 text-white text-xs font-medium rounded hover:bg-teal-800">+ Nueva operación</button>
        </div>
      </div>

      {modo === "resumen" && <ResumenTesoreria {...{ cuentas, saveCuentas, saldos, consolidadoUSD, tcFix, saveTcFix }} />}
      {modo === "flujo" && <FlujoSemanal {...{ operaciones, cuentas, saldos, consolidadoUSD, tcFix, cta }} />}
      {modo === "movimientos" && <Movimientos {...{ operaciones, saveOperaciones, cta, setAviso, onEditar: setEditando }} />}
    </div>
  );
}

function ResumenTesoreria({ cuentas, saveCuentas, saldos, consolidadoUSD, tcFix, saveTcFix }) {
  return (
    <div className="space-y-4">
      {/* Consolidado + TC */}
      <div className="grid grid-cols-1 md:grid-cols-3 gap-2">
        <div className="md:col-span-2 bg-stone-900 text-white rounded-lg p-4 flex items-end justify-between">
          <div>
            <p className="text-[10px] uppercase tracking-widest text-stone-400">Disponible consolidado</p>
            <p className="text-2xl font-semibold font-mono">${mx(consolidadoUSD)} <span className="text-sm text-stone-400">USD</span></p>
          </div>
          <p className="text-[11px] text-stone-400 font-mono">{cuentas.length} cuentas</p>
        </div>
        <div className="bg-white border border-stone-200 rounded-lg p-4">
          <Lbl>TC fix (Banxico)</Lbl>
          <input type="number" step="0.0001" value={tcFix} onChange={(e) => saveTcFix(+e.target.value || 0)}
            className="w-full px-2 py-1.5 text-sm font-mono bg-white border border-stone-300 rounded focus:outline-none focus:ring-2 focus:ring-teal-600" />
          <p className="mt-1 text-[10px] text-stone-400">Convierte los saldos MXN a USD para el total.</p>
        </div>
      </div>

      {/* Cuentas */}
      <div className="bg-white border border-stone-200 rounded-lg overflow-x-auto">
        <table className="w-full min-w-[520px] text-sm">
          <thead className="bg-stone-50 border-b border-stone-200"><tr className="text-[10px] uppercase tracking-widest text-stone-500">
            <th className="text-left px-3 py-2">Cuenta</th><th className="text-left px-3 py-2">Moneda</th>
            <th className="text-right px-3 py-2">Saldo</th><th className="text-right px-3 py-2">USD equiv.</th>
          </tr></thead>
          <tbody>
            {cuentas.map((c) => (
              <tr key={c.id} className="border-b border-stone-100">
                <td className="px-3 py-2 font-medium">{c.nombre}</td>
                <td className="px-3 py-2 font-mono text-xs text-stone-500">{c.moneda}</td>
                <td className="px-3 py-2 text-right font-mono">{mx(saldos[c.id] || 0)}</td>
                <td className="px-3 py-2 text-right font-mono text-stone-500">${mx(enUSD(saldos[c.id] || 0, c.moneda, tcFix))}</td>
              </tr>
            ))}
          </tbody>
        </table>
      </div>
      <p className="text-xs text-stone-500">La proyección semana a semana está en la pestaña <strong>Flujo semanal</strong>.</p>
    </div>
  );
}

/* Flujo semanal estilo Excel: semanas expandibles con filtro por cuenta y rango */
/* Periodos: helpers de agregación temporal */
const inicioPeriodo = (date, nivel) => {
  const d = new Date(date); d.setHours(0, 0, 0, 0);
  if (nivel === "semana") { const day = (d.getDay() + 6) % 7; d.setDate(d.getDate() - day); }
  else if (nivel === "mes") d.setDate(1);
  else if (nivel === "trimestre") { d.setMonth(d.getMonth() - (d.getMonth() % 3), 1); }
  else if (nivel === "año") d.setMonth(0, 1);
  return d;
};
const masPeriodo = (date, nivel, n) => {
  const d = new Date(date);
  if (nivel === "semana") d.setDate(d.getDate() + 7 * n);
  else if (nivel === "mes") d.setMonth(d.getMonth() + n);
  else if (nivel === "trimestre") d.setMonth(d.getMonth() + 3 * n);
  else if (nivel === "año") d.setFullYear(d.getFullYear() + n);
  return d;
};
const etiquetaPeriodo = (date, nivel) => {
  const d = new Date(date);
  if (nivel === "semana") { const fin = masPeriodo(d, "semana", 1); fin.setDate(fin.getDate() - 1); const f = (x) => x.toLocaleDateString("es-MX", { day: "numeric", month: "short" }); return `${f(d)} – ${f(fin)}`; }
  if (nivel === "mes") { const s = d.toLocaleDateString("es-MX", { month: "long", year: "numeric" }); return s.charAt(0).toUpperCase() + s.slice(1); }
  if (nivel === "trimestre") return `Q${Math.floor(d.getMonth() / 3) + 1} ${d.getFullYear()}`;
  return `${d.getFullYear()}`;
};
const VENTANA = { semana: 8, mes: 6, trimestre: 4, año: 3 };

function FlujoSemanal({ operaciones, cuentas, saldos, consolidadoUSD, tcFix, cta }) {
  const [ctaF, setCtaF] = useState("todas");
  const [nivel, setNivel] = useState("semana");
  const [ancla, setAncla] = useState(() => inicioPeriodo(new Date(), "semana").toISOString().slice(0, 10));
  const [abierta, setAbierta] = useState(null);

  const perAccount = ctaF !== "todas";
  const monedaVista = perAccount ? (cta(ctaF)?.moneda || "USD") : "USD";
  const inicio = perAccount ? (saldos[ctaF] || 0) : consolidadoUSD;
  const toVista = (monto, moneda) => (perAccount ? monto : enUSD(monto, moneda, tcFix));

  const cambiarNivel = (nv) => { setNivel(nv); setAncla(inicioPeriodo(new Date(ancla + "T00:00:00"), nv).toISOString().slice(0, 10)); setAbierta(null); };
  const mover = (n) => setAncla(masPeriodo(inicioPeriodo(new Date(ancla + "T00:00:00"), nivel), nivel, n).toISOString().slice(0, 10));
  const hoy = () => setAncla(inicioPeriodo(new Date(), nivel).toISOString().slice(0, 10));

  const movimientos = useMemo(() => {
    const out = [];
    const push = (fecha, dir, monto, o) => out.push({ fecha, dir, monto, o });
    operaciones.filter((o) => o.fecha).forEach((o) => {
      if (o.tipo === "ingreso" && (!perAccount || o.cuentaId === ctaF)) push(o.fecha, "entra", toVista(+o.monto || 0, o.moneda), o);
      else if (o.tipo === "egreso" && (!perAccount || o.cuentaId === ctaF)) push(o.fecha, "sale", toVista(+o.monto || 0, o.moneda), o);
      else if ((o.tipo === "traspaso" || o.tipo === "cambio") && perAccount) {
        if (o.cuentaId === ctaF) push(o.fecha, "sale", toVista(+o.monto || 0, o.moneda), o);
        if (o.cuentaDestinoId === ctaF) { const inM = o.tipo === "cambio" ? (+o.montoDestino || 0) : (+o.monto || 0); push(o.fecha, "entra", toVista(inM, cta(o.cuentaDestinoId)?.moneda), o); }
      }
    });
    return out;
  }, [operaciones, ctaF, perAccount, tcFix]);

  const periodos = useMemo(() => {
    const n = VENTANA[nivel];
    const anclaD = inicioPeriodo(new Date(ancla + "T00:00:00"), nivel);
    const ts = (f) => new Date(f + "T00:00:00").getTime();
    const netConfirmado = movimientos.filter((m) => m.o.estatus === "confirmado").reduce((s, m) => s + (m.dir === "entra" ? m.monto : -m.monto), 0);
    const apertura0 = inicio - netConfirmado;
    let carry = apertura0 + movimientos.filter((m) => ts(m.fecha) < anclaD.getTime()).reduce((s, m) => s + (m.dir === "entra" ? m.monto : -m.monto), 0);
    const res = [];
    for (let i = 0; i < n; i++) {
      const pIni = masPeriodo(anclaD, nivel, i), pFin = masPeriodo(anclaD, nivel, i + 1);
      const items = movimientos.filter((m) => ts(m.fecha) >= pIni.getTime() && ts(m.fecha) < pFin.getTime()).sort((a, b) => a.fecha.localeCompare(b.fecha));
      const apertura = carry; let bal = apertura, min = apertura, entra = 0, sale = 0;
      items.forEach((m) => { if (m.dir === "entra") { bal += m.monto; entra += m.monto; } else { bal -= m.monto; sale += m.monto; } if (bal < min) min = bal; });
      carry = bal;
      res.push({ key: pIni.toISOString().slice(0, 10), label: etiquetaPeriodo(pIni, nivel), entra, sale, cierre: bal, bache: min < 0, items });
    }
    return res;
  }, [movimientos, nivel, ancla, inicio]);

  // Movimientos del periodo visible (confirmados + planeados), según cuenta
  const movsPeriodo = useMemo(() => {
    const anclaD = inicioPeriodo(new Date(ancla + "T00:00:00"), nivel);
    const fin = masPeriodo(anclaD, nivel, VENTANA[nivel]);
    const ts = (f) => new Date(f + "T00:00:00").getTime();
    return operaciones
      .filter((o) => o.fecha && ts(o.fecha) >= anclaD.getTime() && ts(o.fecha) < fin.getTime())
      .filter((o) => !perAccount || o.cuentaId === ctaF || o.cuentaDestinoId === ctaF)
      .sort((a, b) => b.fecha.localeCompare(a.fecha));
  }, [operaciones, ctaF, perAccount, nivel, ancla]);

  const sel = "px-2 py-1.5 text-xs bg-white border border-stone-300 rounded focus:outline-none focus:ring-2 focus:ring-teal-600";
  const anclaLabel = etiquetaPeriodo(inicioPeriodo(new Date(ancla + "T00:00:00"), nivel), nivel);

  return (
    <div className="space-y-3">
      {/* Barra de navegación */}
      <div className="flex flex-wrap items-center gap-2">
        <div className="flex items-center gap-1">
          <button onClick={() => mover(-1)} className="w-8 h-8 rounded border border-stone-300 text-stone-600 hover:bg-stone-100">‹</button>
          <span className="px-2 min-w-[130px] text-center text-sm font-medium">{anclaLabel}</span>
          <button onClick={() => mover(1)} className="w-8 h-8 rounded border border-stone-300 text-stone-600 hover:bg-stone-100">›</button>
        </div>
        <div className="flex rounded border border-stone-300 overflow-hidden">
          {[["semana", "Semana"], ["mes", "Mes"], ["trimestre", "Trim."], ["año", "Año"]].map(([k, t]) => (
            <button key={k} onClick={() => cambiarNivel(k)} className={`px-2.5 py-1.5 text-xs font-medium ${nivel === k ? "bg-stone-900 text-white" : "bg-white text-stone-600 hover:bg-stone-50"}`}>{t}</button>
          ))}
        </div>
        <button onClick={hoy} className="px-2.5 py-1.5 text-xs font-medium rounded border border-stone-300 text-stone-600 hover:bg-stone-50">Hoy</button>
        <select className={sel} value={ctaF} onChange={(e) => setCtaF(e.target.value)}>
          <option value="todas">Todas (USD)</option>
          {cuentas.map((c) => <option key={c.id} value={c.id}>{c.nombre} {c.moneda}</option>)}
        </select>
        <span className="text-[11px] font-mono text-stone-500 ml-auto">Inicio ${mx(inicio)} {monedaVista}</span>
      </div>

      <div className="space-y-2">
        {periodos.map((w) => {
          const neg = w.cierre < 0;
          const open = abierta === w.key;
          const alerta = neg || w.bache;
          return (
            <div key={w.key} className={`bg-white border rounded-lg ${alerta ? "border-red-300" : "border-stone-200"}`}>
              <button onClick={() => setAbierta(open ? null : w.key)} className="w-full px-4 py-3 flex items-center gap-3 text-left hover:bg-stone-50">
                <span className="text-stone-400 text-xs">{open ? "▾" : "▸"}</span>
                <div className="flex-1">
                  <p className="text-sm font-medium">{w.label}</p>
                  <p className="text-[11px] font-mono text-stone-500"><span className="text-teal-700">+${mx(w.entra)}</span> · <span className="text-red-600">−${mx(w.sale)}</span>{w.items.length ? "" : " · sin movimientos"}</p>
                </div>
                <div className="text-right">
                  <p className="text-[10px] uppercase tracking-widest text-stone-400">Saldo al cierre</p>
                  <p className={`font-mono font-semibold ${neg ? "text-red-600" : "text-stone-900"}`}>{neg ? "⚠ " : ""}${mx(w.cierre)}</p>
                  {!neg && w.bache && <p className="text-[10px] text-red-600">⚠ bache negativo dentro del periodo</p>}
                </div>
              </button>
              {open && w.items.length > 0 && (
                <div className="border-t border-stone-100 px-4 py-2 divide-y divide-stone-50">
                  {w.items.map((it, i) => (
                    <div key={i} className="flex items-center justify-between py-1.5 text-xs">
                      <span className="text-stone-600">
                        {it.o.tipo === "ingreso" || it.o.tipo === "egreso" ? it.o.contraparte : TIPOS_OP[it.o.tipo]}
                        {it.o.categoria && <span className="text-stone-400"> · {it.o.categoria}</span>}
                        <span className="text-stone-400"> · {it.fecha}</span>
                      </span>
                      <span className={`font-mono ${it.dir === "entra" ? "text-teal-700" : "text-red-600"}`}>{it.dir === "entra" ? "+" : "−"}${mx(it.monto)}</span>
                    </div>
                  ))}
                </div>
              )}
            </div>
          );
        })}
      </div>
      <p className="text-[11px] text-stone-400">Muestra movimientos <strong>confirmados y planeados</strong>, reconstruyendo el saldo semana a semana hasta el disponible actual y proyectando hacia adelante. El aviso ⚠ marca si el saldo baja de cero, aunque el periodo cierre en positivo.</p>

      {/* Movimientos del periodo visible */}
      <div className="bg-white border border-stone-200 rounded-lg">
        <div className="px-4 py-2.5 border-b border-stone-200 flex items-baseline justify-between">
          <h3 className="text-sm font-semibold">Movimientos del periodo</h3>
          <span className="text-[11px] font-mono text-stone-500">{movsPeriodo.length} movimiento{movsPeriodo.length === 1 ? "" : "s"}</span>
        </div>
        {movsPeriodo.length === 0 ? (
          <p className="p-6 text-sm text-stone-500">Sin movimientos en el rango mostrado. Usa las flechas para moverte o registra operaciones con fecha en este periodo.</p>
        ) : (
          <div className="divide-y divide-stone-50">
            {movsPeriodo.map((o) => {
              const c = cta(o.cuentaId), cd = o.cuentaDestinoId ? cta(o.cuentaDestinoId) : null;
              const detalle = o.tipo === "ingreso" || o.tipo === "egreso" ? o.contraparte : `${c?.nombre} ${c?.moneda} → ${cd?.nombre} ${cd?.moneda}`;
              return (
                <div key={o.id} className="px-4 py-2 flex items-center justify-between gap-2">
                  <div className="min-w-0">
                    <p className="text-xs text-stone-700 truncate">
                      {detalle}
                      {o.categoria && <span className="text-stone-400"> · {o.categoria}</span>}
                    </p>
                    <p className="text-[10px] font-mono text-stone-400">{o.fecha} · {c?.nombre} {c?.moneda}{o.referencia ? ` · ${o.referencia}` : ""}</p>
                  </div>
                  <div className="text-right whitespace-nowrap">
                    <span className={`font-mono text-sm ${o.tipo === "ingreso" ? "text-teal-700" : o.tipo === "egreso" ? "text-red-600" : "text-stone-600"}`}>
                      {o.tipo === "ingreso" ? "+" : o.tipo === "egreso" ? "−" : ""}{mx(o.monto)} <span className="text-[10px] text-stone-400">{o.moneda}</span>
                    </span>
                    <span className={`block text-[10px] font-medium ${o.estatus === "confirmado" ? "text-teal-700" : "text-amber-700"}`}>{o.estatus === "confirmado" ? "Confirmado" : "Planeado"}</span>
                  </div>
                </div>
              );
            })}
          </div>
        )}
      </div>
    </div>
  );
}


function NuevaOperacion({ cuentas, tcFix, onCancel, onSave, inicial }) {
  const [tipo, setTipo] = useState(inicial?.tipo || "egreso");
  const [f, setF] = useState(inicial
    ? { fecha: inicial.fecha || hoy(), cuentaId: inicial.cuentaId || cuentas[0]?.id || "", cuentaDestinoId: inicial.cuentaDestinoId || "", contraparte: inicial.contraparte || "", categoria: inicial.categoria || "", monto: inicial.monto ?? "", montoDestino: inicial.montoDestino ?? "", tc: inicial.tc || tcFix, estatus: inicial.estatus || "confirmado", referencia: inicial.referencia || "", comprobante: inicial.comprobante || "", nota: inicial.nota || "" }
    : { fecha: hoy(), cuentaId: cuentas[0]?.id || "", cuentaDestinoId: "", contraparte: "", categoria: "", monto: "", montoDestino: "", tc: tcFix, estatus: "confirmado", referencia: "", comprobante: "", nota: "" });
  const set = (k, v) => setF((s) => ({ ...s, [k]: v }));
  const inp = "w-full px-2 py-1.5 text-sm bg-white border border-stone-300 rounded focus:outline-none focus:ring-2 focus:ring-teal-600";
  const monedaDe = (id) => cuentas.find((c) => c.id === id)?.moneda || "";

  const guardar = () => {
    if (!f.monto || !f.cuentaId) return;
    if ((tipo === "traspaso" || tipo === "cambio") && !f.cuentaDestinoId) return;
    const moneda = monedaDe(f.cuentaId);
    const op = { id: inicial?.id || uid(), tipo, fecha: f.fecha, cuentaId: f.cuentaId, monto: +f.monto || 0, moneda, estatus: f.estatus, referencia: f.referencia, comprobante: f.comprobante, nota: f.nota };
    if (tipo === "ingreso" || tipo === "egreso") { op.contraparte = f.contraparte; op.categoria = f.categoria; }
    if (tipo === "traspaso") { op.cuentaDestinoId = f.cuentaDestinoId; }
    if (tipo === "cambio") { op.cuentaDestinoId = f.cuentaDestinoId; op.tc = +f.tc || tcFix; op.montoDestino = +f.montoDestino || (monedaDe(f.cuentaId) === "MXN" ? (+f.monto || 0) / (+f.tc || tcFix) : (+f.monto || 0) * (+f.tc || tcFix)); }
    onSave(op);
  };

  const catList = tipo === "ingreso" ? CAT_INGRESO : CAT_EGRESO;
  const editando = !!inicial;

  return (
    <div className="space-y-4">
      <div className="flex items-center justify-between">
        <h2 className="text-sm font-semibold">{editando ? "Editar operación" : "Nueva operación"}</h2>
        <button onClick={onCancel} className="text-xs text-stone-500 hover:text-stone-800">← Volver</button>
      </div>

      {/* Tipo */}
      <div className="grid grid-cols-2 md:grid-cols-4 gap-2">
        {Object.entries(TIPOS_OP).map(([k, v]) => (
          <button key={k} onClick={() => setTipo(k)}
            className={`px-3 py-2 text-xs font-medium rounded border ${tipo === k ? "bg-stone-900 text-white border-stone-900" : "bg-white text-stone-600 border-stone-300"}`}>{v}</button>
        ))}
      </div>

      <div className="bg-white border border-stone-200 rounded-lg p-4 grid grid-cols-2 md:grid-cols-3 gap-3">
        <div><Lbl>Fecha</Lbl><input type="date" className={inp} value={f.fecha} onChange={(e) => set("fecha", e.target.value)} /></div>

        <div><Lbl>{tipo === "traspaso" || tipo === "cambio" ? "Cuenta origen" : "Cuenta"}</Lbl>
          <select className={inp} value={f.cuentaId} onChange={(e) => set("cuentaId", e.target.value)}>
            {cuentas.map((c) => <option key={c.id} value={c.id}>{c.nombre} {c.moneda}</option>)}
          </select></div>

        {(tipo === "traspaso" || tipo === "cambio") && (
          <div><Lbl>Cuenta destino</Lbl>
            <select className={inp} value={f.cuentaDestinoId} onChange={(e) => set("cuentaDestinoId", e.target.value)}>
              <option value="">—</option>
              {cuentas.filter((c) => c.id !== f.cuentaId && (tipo === "cambio" || c.moneda === monedaDe(f.cuentaId))).map((c) => <option key={c.id} value={c.id}>{c.nombre} {c.moneda}</option>)}
            </select></div>
        )}

        {(tipo === "ingreso" || tipo === "egreso") && (
          <>
            <div><Lbl>{tipo === "ingreso" ? "Cliente / proyecto" : "Proveedor"}</Lbl><input className={inp} value={f.contraparte} onChange={(e) => set("contraparte", e.target.value)} /></div>
            <div><Lbl>Categoría</Lbl><select className={inp} value={f.categoria} onChange={(e) => set("categoria", e.target.value)}><option value="">—</option>{catList.map((c) => <option key={c}>{c}</option>)}</select></div>
          </>
        )}

        <div><Lbl>Monto ({monedaDe(f.cuentaId)})</Lbl><input type="number" step="0.01" className={inp + " font-mono text-right"} value={f.monto} onChange={(e) => set("monto", e.target.value)} /></div>

        {tipo === "cambio" && (
          <>
            <div><Lbl>TC de la operación</Lbl><input type="number" step="0.0001" className={inp + " font-mono text-right"} value={f.tc} onChange={(e) => set("tc", e.target.value)} /></div>
            <div><Lbl>Monto recibido ({monedaDe(f.cuentaDestinoId)})</Lbl><input type="number" step="0.01" className={inp + " font-mono text-right"} value={f.montoDestino} onChange={(e) => set("montoDestino", e.target.value)} placeholder="auto si vacío" /></div>
          </>
        )}

        <div><Lbl>Estatus</Lbl><select className={inp} value={f.estatus} onChange={(e) => set("estatus", e.target.value)}>
          <option value="confirmado">Confirmado (ya cayó / pagado)</option>
          <option value="planeado">Planeado (por pagar / esperado)</option>
        </select></div>

        <div><Lbl>Referencia</Lbl><input className={inp} value={f.referencia} onChange={(e) => set("referencia", e.target.value)} placeholder="Factura, SO, PO…" /></div>

        <div className="md:col-span-3">
          <Lbl>Comprobante</Lbl>
          <label className="text-[11px] text-teal-700 cursor-pointer">📎 Adjuntar comprobante
            <input type="file" className="hidden" onChange={(e) => { const file = e.target.files?.[0]; if (file) set("comprobante", file.name); }} />
          </label>
          {f.comprobante && <span className="ml-2 text-[11px] font-mono text-stone-500">{f.comprobante}</span>}
        </div>
      </div>

      <div className="flex gap-2">
        <button onClick={guardar} disabled={!f.monto || !f.cuentaId} className="px-4 py-2 bg-stone-900 text-white text-sm font-medium rounded hover:bg-stone-800 disabled:opacity-40">{editando ? "Guardar cambios" : "Registrar operación"}</button>
        <button onClick={onCancel} className="px-4 py-2 border border-stone-300 text-sm rounded">Cancelar</button>
      </div>
      <p className="text-[11px] text-stone-400">El registro alimenta el flujo y queda listo para empujarse a Zoho (cliente o proveedor) cuando conectemos la escritura. El comprobante físico se guardará ligado en Zoho.</p>
    </div>
  );
}

function Movimientos({ operaciones, saveOperaciones, cta, setAviso, onEditar }) {
  const [filtro, setFiltro] = useState("todos");
  const [confirmando, setConfirmando] = useState(null); // op
  const [paso, setPaso] = useState(1);
  const rows = operaciones.filter((o) => filtro === "todos" || o.tipo === filtro || (filtro === "planeado" && o.estatus === "planeado"));

  const confirmar = (id) => {
    saveOperaciones(operaciones.map((o) => (o.id === id ? { ...o, estatus: "confirmado" } : o)));
    setAviso({ t: "ok", m: "Operación marcada como confirmada." });
  };
  const borrar = (id) => saveOperaciones(operaciones.filter((o) => o.id !== id));

  const pedirEditar = (o) => { setConfirmando(o); setPaso(1); };
  const cerrarModal = () => { setConfirmando(null); setPaso(1); };
  const seguir = () => { if (paso === 1) setPaso(2); else { const o = confirmando; cerrarModal(); onEditar(o); } };

  const quien = confirmando ? (confirmando.tipo === "ingreso" ? `el cliente “${confirmando.contraparte || "—"}”` : confirmando.tipo === "egreso" ? `el proveedor “${confirmando.contraparte || "—"}”` : "un traspaso entre cuentas") : "";
  const banco = confirmando ? `${cta(confirmando.cuentaId)?.nombre || ""} ${cta(confirmando.cuentaId)?.moneda || ""}` : "";

  return (
    <div className="space-y-3">
      <div className="flex flex-wrap gap-1">
        {[["todos", "Todos"], ["ingreso", "Ingresos"], ["egreso", "Egresos"], ["traspaso", "Traspasos"], ["cambio", "Cambios"], ["planeado", "Planeados"]].map(([k, t]) => (
          <button key={k} onClick={() => setFiltro(k)} className={`px-2.5 py-1.5 text-xs rounded ${filtro === k ? "bg-stone-900 text-white" : "border border-stone-300 text-stone-600"}`}>{t}</button>
        ))}
      </div>
      {rows.length === 0 ? (
        <div className="bg-white border border-stone-200 rounded-lg p-8 text-center text-sm text-stone-500">Sin operaciones. Registra la primera con "+ Nueva operación".</div>
      ) : (
        <div className="bg-white border border-stone-200 rounded-lg overflow-x-auto">
          <table className="w-full min-w-[760px] text-sm">
            <thead className="bg-stone-50 border-b border-stone-200"><tr className="text-[10px] uppercase tracking-widest text-stone-500">
              <th className="text-left px-3 py-2">Fecha</th><th className="text-left px-3 py-2">Tipo</th><th className="text-left px-3 py-2">Detalle</th>
              <th className="text-left px-3 py-2">Cuenta</th><th className="text-right px-3 py-2">Monto</th><th className="text-left px-3 py-2">Estatus</th><th className="px-3 py-2"></th>
            </tr></thead>
            <tbody>
              {rows.slice(0, 300).map((o) => {
                const c = cta(o.cuentaId), cd = o.cuentaDestinoId ? cta(o.cuentaDestinoId) : null;
                return (
                  <tr key={o.id} className="border-b border-stone-100">
                    <td className="px-3 py-2 font-mono text-xs">{o.fecha}</td>
                    <td className="px-3 py-2 text-xs">{TIPOS_OP[o.tipo]}</td>
                    <td className="px-3 py-2 text-xs text-stone-600">
                      {o.tipo === "traspaso" || o.tipo === "cambio" ? `→ ${cd?.nombre} ${cd?.moneda}` : o.contraparte}
                      {o.categoria && <span className="text-stone-400"> · {o.categoria}</span>}
                      {o.comprobante && <span className="text-teal-600"> · 📎</span>}
                    </td>
                    <td className="px-3 py-2 text-xs">{c?.nombre} {c?.moneda}</td>
                    <td className={`px-3 py-2 text-right font-mono ${o.tipo === "ingreso" ? "text-teal-700" : o.tipo === "egreso" ? "text-red-600" : "text-stone-600"}`}>
                      {o.tipo === "ingreso" ? "+" : o.tipo === "egreso" ? "−" : ""}{mx(o.monto)}
                    </td>
                    <td className="px-3 py-2">
                      <span className={`px-2 py-0.5 text-[10px] rounded font-medium ${o.estatus === "confirmado" ? "bg-teal-100 text-teal-800" : "bg-amber-100 text-amber-800"}`}>{o.estatus === "confirmado" ? "Confirmado" : "Planeado"}</span>
                    </td>
                    <td className="px-3 py-2 text-right whitespace-nowrap">
                      <button onClick={() => pedirEditar(o)} className="px-2 py-1 text-[11px] text-stone-600 hover:bg-stone-100 rounded">Editar</button>
                      {o.estatus === "planeado" && <button onClick={() => confirmar(o.id)} className="px-2 py-1 text-[11px] text-teal-700 hover:bg-teal-50 rounded">Confirmar</button>}
                      <button onClick={() => borrar(o.id)} className="px-2 py-1 text-[11px] text-stone-400 hover:text-red-600">×</button>
                    </td>
                  </tr>
                );
              })}
            </tbody>
          </table>
        </div>
      )}

      {/* Modal ¡AGUAS! doble confirmación */}
      {confirmando && (
        <div className="fixed inset-0 z-50 flex items-center justify-center bg-black/50 p-4" onClick={cerrarModal}>
          <div className="bg-white rounded-xl max-w-md w-full p-5 shadow-xl" onClick={(e) => e.stopPropagation()}>
            {paso === 1 ? (
              <>
                <p className="text-2xl mb-1">🚨 ¡AGUAS!</p>
                <p className="text-sm text-stone-700 leading-relaxed">
                  Estás por editar un movimiento que <strong>afecta saldos de banco</strong> ({banco}) y el registro de <strong>{quien}</strong>.
                  Cambiarlo mueve tu flujo y, al conectar Zoho, también el registro del cliente/proveedor.
                </p>
                <p className="mt-2 text-sm font-medium">¿Seguro que quieres editar?</p>
                <div className="mt-4 flex gap-2 justify-end">
                  <button onClick={cerrarModal} className="px-4 py-2 text-sm rounded border border-stone-300">Cancelar</button>
                  <button onClick={seguir} className="px-4 py-2 text-sm rounded bg-amber-500 text-white font-medium">Sí, editar</button>
                </div>
              </>
            ) : (
              <>
                <p className="text-2xl mb-1">⚠️ Última oportunidad… ¡AGUAS!</p>
                <p className="text-sm text-stone-700 leading-relaxed">En serio: esto reescribe el movimiento y recalcula el saldo de {banco}. Si te equivocas, descuadra la cuenta.</p>
                <p className="mt-2 text-sm font-medium">¿De verdad, de verdad?</p>
                <div className="mt-4 flex gap-2 justify-end">
                  <button onClick={cerrarModal} className="px-4 py-2 text-sm rounded border border-stone-300">Mejor no</button>
                  <button onClick={seguir} className="px-4 py-2 text-sm rounded bg-red-600 text-white font-medium">Editar de todas formas</button>
                </div>
              </>
            )}
          </div>
        </div>
      )}
    </div>
  );
}

/* ===================== UI helpers ===================== */
function Section({ n, t, r, children }) {
  return (
    <section className="bg-white border border-stone-200 rounded-lg">
      <div className="px-4 py-2.5 border-b border-stone-200 flex flex-wrap items-baseline justify-between gap-2">
        <h3 className="text-sm font-semibold"><span className="font-mono text-[11px] text-amber-600 mr-2">{n}</span>{t}</h3>
        {r && <span className="font-mono text-xs text-stone-500">{r}</span>}
      </div>
      {children}
    </section>
  );
}
const Lbl = ({ children }) => <label className="block text-[10px] font-semibold tracking-widest uppercase text-stone-500 mb-1">{children}</label>;
const Field = ({ l, children }) => <div><Lbl>{l}</Lbl>{children}</div>;
